Require Import Language Dev0 CompTest Occ Syn FixTP FixCO Ren RenOpen Erase Ctx Subst Pclosed.
From Stdlib Require Import Lia List.
Set Implicit Arguments.

Definition pclosed_sort (s:sort) : Prop :=
  match s with
  | Tm A => pclosed_tm 0 0 A
  | Co p => pclosed_con 0 0 p
  end.

Fixpoint AnnTyping_pclosed (G:context) (a A:tm) (d:AnnTyping G a A) {struct d} :
  pclosed_tm 0 0 a /\ pclosed_tm 0 0 A :=
  match d as d0 in AnnTyping G0 a0 A0 return (pclosed_tm 0 0 a0 /\ pclosed_tm 0 0 A0) with
  | An_Star G0 HC => conj I I
  | An_Var G0 x A0 HC Hb => conj I (@AnnCtx_pclosed G0 HC x (Tm A0) Hb)
  | An_Pi L G0 rho A0 B0 Hbody HA => ltac:(
      assert (Hpa := proj1 (@AnnTyping_pclosed G0 A0 a_Star HA));
      destruct (atom_fresh L) as [z Hz];
      assert (Hpb := proj1 (@AnnTyping_pclosed ((z ~ Tm A0) ++ G0) (open_tm_wrt_tm B0 (a_Var_f z)) a_Star (Hbody z Hz)));
      assert (HpB : pclosed_tm 1 0 B0) by (eapply pclosed_raise_tm; exact Hpb);
      split; [ split; [ exact Hpa | exact HpB ] | exact I ])
  | An_Abs L G0 rho A0 a0 B0 HA Hbody HR => ltac:(
      assert (Hpa := proj1 (@AnnTyping_pclosed G0 A0 a_Star HA));
      destruct (atom_fresh L) as [z Hz];
      assert (Hbody_p := @AnnTyping_pclosed ((z ~ Tm A0) ++ G0) (open_tm_wrt_tm a0 (a_Var_f z)) (open_tm_wrt_tm B0 (a_Var_f z)) (Hbody z Hz));
      assert (Hpa0 : pclosed_tm 1 0 a0) by (eapply pclosed_raise_tm; exact (proj1 Hbody_p));
      assert (HpB : pclosed_tm 1 0 B0) by (eapply pclosed_raise_tm; exact (proj2 Hbody_p));
      split; [ split; [ exact Hpa | exact Hpa0 ] | split; [ exact Hpa | exact HpB ] ])
  | An_App G0 b rho a0 B0 A0 Htyp Ha => ltac:(
      assert (Hb := @AnnTyping_pclosed G0 b (a_Pi rho A0 B0) Htyp);
      assert (Ha_p := proj1 (@AnnTyping_pclosed G0 a0 A0 Ha));
      assert (HpB : pclosed_tm 1 0 B0) by exact (proj2 (proj2 Hb));
      assert (Hptype : pclosed_tm 0 0 (open_tm_wrt_tm B0 a0)) by
        (change (pclosed_tm 0 0 (open_tm_wrt_tm_rec 0 a0 B0));
         exact (pclosed_open_tm B0 0 0 a0 HpB Ha_p));
      split; [ split; [ exact (proj1 Hb) | exact Ha_p ] | exact Hptype ])
  | An_Conv G0 a0 g B0 A0 Htyp Hde Hwf => ltac:(
      assert (Ha_p := proj1 (@AnnTyping_pclosed G0 a0 A0 Htyp));
      assert (Hg := @AnnDefEq_pclosed G0 (dom G0) g A0 B0 Hde);
      assert (HB := proj1 (@AnnTyping_pclosed G0 B0 a_Star Hwf));
      split; [ split; [ exact Ha_p | exact Hg ] | exact HB ])
  | An_CPi L G0 phi B0 Hprop Hbody => ltac:(
      assert (Hphi := @AnnPropWff_pclosed G0 phi Hprop);
      destruct (atom_fresh L) as [z Hz];
      assert (HB := proj1 (@AnnTyping_pclosed ((z ~ Co phi) ++ G0) (open_tm_wrt_co B0 (g_Var_f z)) a_Star (Hbody z Hz)));
      assert (HpB : pclosed_tm 0 1 B0) by (eapply pclosed_raise_co; exact HB);
      split; [ split; [ exact Hphi | exact HpB ] | exact I ])
  | An_CAbs L G0 phi a0 B0 Hprop Hbody => ltac:(
      assert (Hphi := @AnnPropWff_pclosed G0 phi Hprop);
      destruct (atom_fresh L) as [z Hz];
      assert (Hbody_p := @AnnTyping_pclosed ((z ~ Co phi) ++ G0) (open_tm_wrt_co a0 (g_Var_f z)) (open_tm_wrt_co B0 (g_Var_f z)) (Hbody z Hz));
      assert (Hpa : pclosed_tm 0 1 a0) by (eapply pclosed_raise_co; exact (proj1 Hbody_p));
      assert (HpB : pclosed_tm 0 1 B0) by (eapply pclosed_raise_co; exact (proj2 Hbody_p));
      split; [ split; [ exact Hphi | exact Hpa ] | split; [ exact Hphi | exact HpB ] ])
  | An_CApp G0 a1 g B0 a0 b0 A1 Htyp Hde => ltac:(
      assert (H1 := @AnnTyping_pclosed G0 a1 (a_CPi (Eq a0 b0 A1) B0) Htyp);
      assert (Hg := @AnnDefEq_pclosed G0 (dom G0) g a0 b0 Hde);
      assert (HpB : pclosed_tm 0 1 B0) by exact (proj2 (proj2 H1));
      assert (Hptype : pclosed_tm 0 0 (open_tm_wrt_co B0 g)) by
        (change (pclosed_tm 0 0 (open_tm_wrt_co_rec 0 g B0));
         exact (pclosed_open_co B0 0 0 g HpB Hg));
      split; [ split; [ exact (proj1 H1) | exact Hg ] | exact Hptype ])
  | An_Fam G0 F A0 a0 HC Hb Hty => ltac:(
      assert (HA := proj1 (@AnnTyping_pclosed nil A0 a_Star Hty));
      split; [ exact I | exact HA ])
  end
with AnnPropWff_pclosed (G:context) (phi:constraint) (d:AnnPropWff G phi) {struct d} :
  pclosed_con 0 0 phi :=
  match d as d0 in AnnPropWff G0 p0 return (pclosed_con 0 0 p0) with
  | An_Wff G0 a0 b0 A0 B0 d1 d2 Heq => ltac:(
      assert (H1 := @AnnTyping_pclosed G0 a0 A0 d1);
      assert (H2 := @AnnTyping_pclosed G0 b0 B0 d2);
      split; [ exact (proj1 H1) | split; [ exact (proj1 H2) | exact (proj2 H1) ] ])
  end
with AnnIso_pclosed (G:context) (D:available_props) (g:co) (p1 p2:constraint)
    (d:AnnIso G D g p1 p2) {struct d} : pclosed_co 0 0 g :=
  match d as d0 in AnnIso G0 D0 g0 p10 p20 return (pclosed_co 0 0 g0) with
  | An_PropCong G0 D0 g1 A0 g2 A1 B1 A2 B2 Hd1 Hd2 Hp1 Hp2 => ltac:(
      assert (H1 := @AnnDefEq_pclosed G0 D0 g1 A1 A2 Hd1);
      assert (H2 := @AnnDefEq_pclosed G0 D0 g2 B1 B2 Hd2);
      assert (Hp := @AnnPropWff_pclosed G0 (Eq A1 B1 A0) Hp1);
      split; [ exact H1 | split; [ exact (proj2 (proj2 Hp)) | exact H2 ] ])
  | An_CPiFst G0 D0 g0 phi1 phi2 A2 B2 Hd => ltac:(
      exact (@AnnDefEq_pclosed G0 D0 g0 (a_CPi phi1 A2) (a_CPi phi2 B2) Hd))
  | An_IsoSym G0 D0 g0 phi2 phi1 Hi => ltac:(
      exact (@AnnIso_pclosed G0 D0 g0 phi2 phi1 Hi))
  | An_IsoConv G0 D0 a1 a2 A0 a1' a2' B0 g0 Hd Hp1 Hp2 He1 He2 => ltac:(
      assert (Hp1' := @AnnPropWff_pclosed G0 (Eq a1 a2 A0) Hp1);
      assert (Hp2' := @AnnPropWff_pclosed G0 (Eq a1' a2' B0) Hp2);
      assert (Hg := @AnnDefEq_pclosed G0 D0 g0 A0 B0 Hd);
      split; [ exact Hp1' | split; [ exact Hp2' | exact Hg ] ])
  end
with AnnDefEq_pclosed (G:context) (D:available_props) (g:co) (a b:tm)
    (d:AnnDefEq G D g a b) {struct d} : pclosed_co 0 0 g :=
  match d as d0 in AnnDefEq G0 D0 g0 a0 b0 return (pclosed_co 0 0 g0) with
  | An_Assn G0 D0 c a0 b0 A0 HC Hb Hin => I
  | An_Refl G0 D0 a0 A0 Ht => ltac:(exact (proj1 (@AnnTyping_pclosed G0 a0 A0 Ht)))
  | An_EraseEq G0 D0 a0 b0 g0 A0 B0 Hta Htb He Hd => ltac:(
      assert (Ha := proj1 (@AnnTyping_pclosed G0 a0 A0 Hta));
      assert (Hb := proj1 (@AnnTyping_pclosed G0 b0 B0 Htb));
      assert (Hg := @AnnDefEq_pclosed G0 (dom G0) g0 A0 B0 Hd);
      split; [ exact Ha | split; [ exact Hb | exact Hg ] ])
  | An_Sym G0 D0 g0 a0 b0 B0 A0 g1 Htb Hta Hde Hd => ltac:(
      exact (@AnnDefEq_pclosed G0 D0 g0 b0 a0 Hd))
  | An_Trans G0 D0 g1 g2 a0 b0 a1 A0 A1 g3 Hd1 Hd2 Hta Hta1 Hde => ltac:(
      assert (H1 := @AnnDefEq_pclosed G0 D0 g1 a0 a1 Hd1);
      assert (H2 := @AnnDefEq_pclosed G0 D0 g2 a1 b0 Hd2);
      split; [ exact H1 | exact H2 ])
  | An_Beta G0 D0 a1 a2 B0 B1 Hta Htb He Hbeta => ltac:(
      assert (H1 := proj1 (@AnnTyping_pclosed G0 a1 B0 Hta));
      assert (H2 := proj1 (@AnnTyping_pclosed G0 a2 B1 Htb));
      split; [ exact H1 | exact H2 ])
  | An_PiCong L G0 D0 rho g1 g2 A1 B1 A2 B3 B2 Hd1 Hd2 Heq Hta1 Hta2 Hta3 => ltac:(
      assert (H1 := @AnnDefEq_pclosed G0 D0 g1 A1 A2 Hd1);
      destruct (atom_fresh L) as [z Hz];
      assert (H2 := @AnnDefEq_pclosed ((z ~ Tm A1) ++ G0) D0 (open_co_wrt_tm g2 (a_Var_f z))
                       (open_tm_wrt_tm B1 (a_Var_f z)) (open_tm_wrt_tm B2 (a_Var_f z)) (Hd2 z Hz));
      assert (H2r : pclosed_co 1 0 g2) by (eapply pclosed_raise_co_tm; exact H2);
      split; [ exact H1 | exact H2r ])
  | An_AbsCong L G0 D0 rho g1 g2 A1 b1 A2 b3 b2 B0 Hd1 Hd2 Heq Hta1 Hta2 HR1 HR3 Hta => ltac:(
      assert (H1 := @AnnDefEq_pclosed G0 D0 g1 A1 A2 Hd1);
      destruct (atom_fresh L) as [z Hz];
