  forall (nt nc:nat), pclosed_tm nt nc t ->
    forall k, nc <= k -> forall g, open_tm_wrt_co_rec k g t = t :=
  match t as t0 return (forall (nt nc:nat), pclosed_tm nt nc t0 ->
    forall k, nc <= k -> forall g, open_tm_wrt_co_rec k g t0 = t0) with
  | a_Star => fun nt nc H k Hk g => eq_refl
  | a_Var_b m => fun nt nc H k Hk g => eq_refl
  | a_Var_f y => fun nt nc H k Hk g => eq_refl
