      cbn [pclosed_tm] in H; destruct H as [HA Hb];
      cbn [open_tm_wrt_co_rec]; f_equal;
      [ exact (pic_tm A nt nc HA k Hk g) | exact (pic_tm b (S nt) nc Hb k Hk g) ])
