Require Import Language Dev0 CompTest Occ Syn FixTP FixCO Ren RenOpen Erase Ctx Subst Pclosed AnnPclosed Commute.
From Stdlib Require Import Lia List.
Set Implicit Arguments.

Lemma binds_weak_tail : forall (A B:context) y s, binds y s B -> binds y s (A ++ B).
Proof.
  intros A. induction A as [|[z t] A IH]; intros B y s H; simpl.
  - exact H.
  - right. apply IH. exact H.
Qed.

Lemma dom_app : forall (A B:context), dom (A ++ B) = dom A \u dom B.
Proof.
  intros A. induction A as [|[z t] A IH]; intros B; simpl.
  - rewrite union_empty_l. reflexivity.
  - rewrite IH. rewrite union_assoc. reflexivity.
Qed.

Lemma AnnTyping_pi_inv : forall G rho A B, AnnTyping G (a_Pi rho A B) a_Star -> AnnTyping G A a_Star.
Proof.
  intros G rho A B H. inversion H; subst; try assumption; try discriminate.
Qed.

Lemma AnnTyping_cpi_inv : forall G phi B, AnnTyping G (a_CPi phi B) a_Star -> AnnPropWff G phi.
Proof.
  intros G phi B H. inversion H; subst; try assumption; try discriminate.
Qed.

Lemma AnnTyping_cabs_inv : forall G phi a B, AnnTyping G (a_CAbs phi a) (a_CPi phi B) -> AnnPropWff G phi.
Proof.
  intros G phi a B H. inversion H; subst; try assumption; try discriminate.
Qed.

(* =====================================================================
   Weakening for the annotated judgments.
   D is extended with dom Γ for the prop-irrelevant judgments.
   ===================================================================== *)

Fixpoint AnnTyping_weak (G:context) (a A:tm) (d:AnnTyping G a A) {struct d} :
  forall Γ, AnnCtx (Γ ++ G) -> AnnTyping (Γ ++ G) a A :=
  match d as d0 in AnnTyping G0 a0 A0 return (forall Γ, AnnCtx (Γ ++ G0) -> AnnTyping (Γ ++ G0) a0 A0) with
  | An_Star G0 HC => fun Γ W => An_Star (Γ ++ G0) W
  | An_Var G0 x A0 HC Hb => fun Γ W => An_Var (Γ ++ G0) x A0 W (binds_weak_tail Hb)
  | An_Pi L G0 rho A0 B0 Hbody HA => fun Γ W => ltac:(
      assert (HA' := AnnTyping_weak HA Γ W);
      apply (An_Pi (L \u dom (Γ ++ G0)) (Γ ++ G0) rho A0 B0);
      [ intros x Hx;
        assert (HxL : x \notin L) by fsetdec;
        assert (Hxd : x \notin dom (Γ ++ G0)) by fsetdec;
        assert (Wx : AnnCtx ((x ~ Tm A0) ++ (Γ ++ G0))) by (apply An_ConsTm; [ exact W | exact HA' | exact Hxd ]);
        rewrite <- (@List.app_assoc (x ~ Tm A0) Γ G0) in Wx;
        exact (AnnTyping_weak (Hbody x HxL) ((x ~ Tm A0) ++ Γ) Wx)
      | exact HA' ])
  | An_Abs L G0 rho A0 a0 B0 HA Hbody HR => fun Γ W => ltac:(
      assert (HA' := AnnTyping_weak HA Γ W);
      apply (An_Abs (L \u dom (Γ ++ G0)) (Γ ++ G0) rho A0 a0 B0);
      [ exact HA'
      | intros x Hx;
        assert (HxL : x \notin L) by fsetdec;
        assert (Hxd : x \notin dom (Γ ++ G0)) by fsetdec;
        assert (Wx : AnnCtx ((x ~ Tm A0) ++ (Γ ++ G0))) by (apply An_ConsTm; [ exact W | exact HA' | exact Hxd ]);
        rewrite <- (@List.app_assoc (x ~ Tm A0) Γ G0) in Wx;
        exact (AnnTyping_weak (Hbody x HxL) ((x ~ Tm A0) ++ Γ) Wx)
      | intros x Hx; apply HR; fsetdec ])
  | An_App G0 b rho a0 B0 A0 Htyp Ha => fun Γ W => ltac:(
      apply (An_App (Γ ++ G0) b rho a0 B0 A0);
      [ exact (AnnTyping_weak Htyp Γ W) | exact (AnnTyping_weak Ha Γ W) ])
  | An_Conv G0 a0 g B0 A0 Htyp Hde Hwf => fun Γ W => ltac:(
      assert (Hde' := AnnDefEq_weak Hde Γ W);
      rewrite (@dom_app Γ G0) in Hde';
      apply (An_Conv (Γ ++ G0) a0 g B0 A0);
      [ exact (AnnTyping_weak Htyp Γ W) | exact Hde' | exact (AnnTyping_weak Hwf Γ W) ])
  | An_CPi L G0 phi B0 Hprop Hbody => fun Γ W => ltac:(
      assert (Hprop' := AnnPropWff_weak Hprop Γ W);
      apply (An_CPi (L \u dom (Γ ++ G0)) (Γ ++ G0) phi B0);
      [ exact Hprop'
      | intros c Hc;
        assert (HcL : c \notin L) by fsetdec;
        assert (Hcd : c \notin dom (Γ ++ G0)) by fsetdec;
        assert (Wc : AnnCtx ((c ~ Co phi) ++ (Γ ++ G0))) by (apply An_ConsCo; [ exact W | exact Hprop' | exact Hcd ]);
        rewrite <- (@List.app_assoc (c ~ Co phi) Γ G0) in Wc;
        exact (AnnTyping_weak (Hbody c HcL) ((c ~ Co phi) ++ Γ) Wc) ])
  | An_CAbs L G0 phi a0 B0 Hprop Hbody => fun Γ W => ltac:(
      assert (Hprop' := AnnPropWff_weak Hprop Γ W);
      apply (An_CAbs (L \u dom (Γ ++ G0)) (Γ ++ G0) phi a0 B0);
      [ exact Hprop'
      | intros c Hc;
        assert (HcL : c \notin L) by fsetdec;
        assert (Hcd : c \notin dom (Γ ++ G0)) by fsetdec;
        assert (Wc : AnnCtx ((c ~ Co phi) ++ (Γ ++ G0))) by (apply An_ConsCo; [ exact W | exact Hprop' | exact Hcd ]);
        rewrite <- (@List.app_assoc (c ~ Co phi) Γ G0) in Wc;
        exact (AnnTyping_weak (Hbody c HcL) ((c ~ Co phi) ++ Γ) Wc) ])
  | An_CApp G0 a1 g B0 a0 b0 A1 Htyp Hde => fun Γ W => ltac:(
      assert (Hde' := AnnDefEq_weak Hde Γ W);
      rewrite (@dom_app Γ G0) in Hde';
      apply (An_CApp (Γ ++ G0) a1 g B0 a0 b0 A1);
      [ exact (AnnTyping_weak Htyp Γ W) | exact Hde' ])
  | An_Fam G0 F A0 a0 HC Hb Hty => fun Γ W => ltac:(
      apply (An_Fam (Γ ++ G0) F A0 a0);
      [ exact W | exact Hb | exact Hty ])
  end
with AnnPropWff_weak (G:context) (phi:constraint) (d:AnnPropWff G phi) {struct d} :
  forall Γ, AnnCtx (Γ ++ G) -> AnnPropWff (Γ ++ G) phi :=
  match d as d0 in AnnPropWff G0 p0 return (forall Γ, AnnCtx (Γ ++ G0) -> AnnPropWff (Γ ++ G0) p0) with
  | An_Wff G0 a0 b0 A0 B0 d1 d2 Heq => fun Γ W => ltac:(
      apply (An_Wff (Γ ++ G0) a0 b0 A0 B0);
      [ exact (AnnTyping_weak d1 Γ W) | exact (AnnTyping_weak d2 Γ W) | exact Heq ])
  end
with AnnIso_weak (G:context) (D:available_props) (g:co) (p1 p2:constraint)
    (d:AnnIso G D g p1 p2) {struct d} :
  forall Γ, AnnCtx (Γ ++ G) -> AnnIso (Γ ++ G) (D \u dom Γ) g p1 p2 :=
  match d as d0 in AnnIso G0 D0 g0 p10 p20 return
    (forall Γ, AnnCtx (Γ ++ G0) -> AnnIso (Γ ++ G0) (D0 \u dom Γ) g0 p10 p20) with
  | An_PropCong G0 D0 g1 A0 g2 A1 B1 A2 B2 Hd1 Hd2 Hp1 Hp2 => fun Γ W => ltac:(
      apply (An_PropCong (Γ ++ G0) (D0 \u dom Γ) g1 A0 g2 A1 B1 A2 B2);
      [ exact (AnnDefEq_weak Hd1 Γ W) | exact (AnnDefEq_weak Hd2 Γ W)
      | exact (AnnPropWff_weak Hp1 Γ W) | exact (AnnPropWff_weak Hp2 Γ W) ])
  | An_CPiFst G0 D0 g0 phi1 phi2 A2 B2 Hd => fun Γ W => ltac:(
      apply (An_CPiFst (Γ ++ G0) (D0 \u dom Γ) g0 phi1 phi2 A2 B2);
      exact (AnnDefEq_weak Hd Γ W))
  | An_IsoSym G0 D0 g0 phi2 phi1 Hi => fun Γ W => ltac:(
      apply (An_IsoSym (Γ ++ G0) (D0 \u dom Γ) g0 phi2 phi1);
