  | An_IsoConv G0 D0 a1 a2 A0 a1' a2' B0 g0 Hd Hp1 Hp2 He1 He2 => fun Γ W => ltac:(
      apply (An_IsoConv (Γ ++ G0) (D0 \u dom Γ) a1 a2 A0 a1' a2' B0 g0);
      [ exact (AnnDefEq_weak Hd Γ W)
      | exact (AnnPropWff_weak Hp1 Γ W) | exact (AnnPropWff_weak Hp2 Γ W)
      | exact He1 | exact He2 ])
  end
with AnnDefEq_weak (G:context) (D:available_props) (g:co) (a b:tm)
    (d:AnnDefEq G D g a b) {struct d} :
  forall Γ, AnnCtx (Γ ++ G) -> AnnDefEq (Γ ++ G) (D \u dom Γ) g a b :=
  match d as d0 in AnnDefEq G0 D0 g0 a0 b0 return
    (forall Γ, AnnCtx (Γ ++ G0) -> AnnDefEq (Γ ++ G0) (D0 \u dom Γ) g0 a0 b0) with
  | An_Assn G0 D0 c a0 b0 A0 HC Hb Hin => fun Γ W => ltac:(
      apply (An_Assn (Γ ++ G0) (D0 \u dom Γ) c a0 b0 A0);
      [ exact W | exact (binds_weak_tail Hb) | apply union_introl; exact Hin ])
  | An_Refl G0 D0 a0 A0 Ht => fun Γ W => ltac:(
      apply (An_Refl (Γ ++ G0) (D0 \u dom Γ) a0 A0);
      exact (AnnTyping_weak Ht Γ W))
  | An_EraseEq G0 D0 a0 b0 g0 A0 B0 Hta Htb He Hd => fun Γ W => ltac:(
      assert (Hd' := AnnDefEq_weak Hd Γ W);
      rewrite (@dom_app Γ G0) in Hd';
      apply (An_EraseEq (Γ ++ G0) (D0 \u dom Γ) a0 b0 g0 A0 B0);
      [ exact (AnnTyping_weak Hta Γ W) | exact (AnnTyping_weak Htb Γ W) | exact He | exact Hd' ])
  | An_Sym G0 D0 g0 a0 b0 B0 A0 g1 Htb Hta Hde Hd => fun Γ W => ltac:(
      assert (Hde' := AnnDefEq_weak Hde Γ W);
      rewrite (@dom_app Γ G0) in Hde';
      apply (An_Sym (Γ ++ G0) (D0 \u dom Γ) g0 a0 b0 B0 A0 g1);
      [ exact (AnnTyping_weak Htb Γ W) | exact (AnnTyping_weak Hta Γ W)
      | exact Hde' | exact (AnnDefEq_weak Hd Γ W) ])
  | An_Trans G0 D0 g1 g2 a0 b0 a1 A0 A1 g3 Hd1 Hd2 Hta Hta1 Hde => fun Γ W => ltac:(
      assert (Hde' := AnnDefEq_weak Hde Γ W);
      rewrite (@dom_app Γ G0) in Hde';
      apply (An_Trans (Γ ++ G0) (D0 \u dom Γ) g1 g2 a0 b0 a1 A0 A1 g3);
      [ exact (AnnDefEq_weak Hd1 Γ W) | exact (AnnDefEq_weak Hd2 Γ W)
      | exact (AnnTyping_weak Hta Γ W) | exact (AnnTyping_weak Hta1 Γ W) | exact Hde' ])
  | An_Beta G0 D0 a1 a2 B0 B1 Hta Htb He Hbeta => fun Γ W => ltac:(
      apply (An_Beta (Γ ++ G0) (D0 \u dom Γ) a1 a2 B0 B1);
      [ exact (AnnTyping_weak Hta Γ W) | exact (AnnTyping_weak Htb Γ W) | exact He | exact Hbeta ])
  | An_PiCong L G0 D0 rho g1 g2 A1 B1 A2 B3 B2 Hd1 Hd2 Heq Hta1 Hta2 Hta3 => fun Γ W => ltac:(
      assert (HA1 := AnnTyping_weak (AnnTyping_pi_inv Hta1) Γ W);
      assert (Hd1' := AnnDefEq_weak Hd1 Γ W);
      apply (An_PiCong (L \u dom (Γ ++ G0)) (Γ ++ G0) (D0 \u dom Γ) rho g1 g2 A1 B1 A2 B3 B2);
      [ exact Hd1'
      | intros x Hx;
        assert (HxL : x \notin L) by fsetdec;
        assert (Hxd : x \notin dom (Γ ++ G0)) by fsetdec;
        assert (Wx : AnnCtx ((x ~ Tm A1) ++ (Γ ++ G0))) by (apply An_ConsTm; [ exact W | exact HA1 | exact Hxd ]);
        rewrite <- (@List.app_assoc (x ~ Tm A1) Γ G0) in Wx;
        exact (AnnDefEq_weak (Hd2 x HxL) ((x ~ Tm A1) ++ Γ) Wx)
      | exact Heq
      | exact (AnnTyping_weak Hta1 Γ W) | exact (AnnTyping_weak Hta2 Γ W) | exact (AnnTyping_weak Hta3 Γ W) ])
  | An_AbsCong L G0 D0 rho g1 g2 A1 b1 A2 b3 b2 B0 Hd1 Hd2 Heq Hta1 Hta2 HR1 HR3 Hta => fun Γ W => ltac:(
      assert (HA1 := AnnTyping_weak Hta1 Γ W);
      assert (Hd1' := AnnDefEq_weak Hd1 Γ W);
      apply (An_AbsCong (L \u dom (Γ ++ G0)) (Γ ++ G0) (D0 \u dom Γ) rho g1 g2 A1 b1 A2 b3 b2 B0);
      [ exact Hd1'
      | intros x Hx;
        assert (HxL : x \notin L) by fsetdec;
        assert (Hxd : x \notin dom (Γ ++ G0)) by fsetdec;
        assert (Wx : AnnCtx ((x ~ Tm A1) ++ (Γ ++ G0))) by (apply An_ConsTm; [ exact W | exact HA1 | exact Hxd ]);
        rewrite <- (@List.app_assoc (x ~ Tm A1) Γ G0) in Wx;
        exact (AnnDefEq_weak (Hd2 x HxL) ((x ~ Tm A1) ++ Γ) Wx)
      | exact Heq
      | exact HA1 | exact (AnnTyping_weak Hta2 Γ W)
      | exact HR1 | exact HR3
      | exact (AnnTyping_weak Hta Γ W) ])
  | An_AppCong G0 D0 g1 rho g2 a1 a2 b1 b2 A0 B0 g3 Hd1 Hd2 Hta Htb Hde => fun Γ W => ltac:(
      assert (Hde' := AnnDefEq_weak Hde Γ W);
      rewrite (@dom_app Γ G0) in Hde';
      apply (An_AppCong (Γ ++ G0) (D0 \u dom Γ) g1 rho g2 a1 a2 b1 b2 A0 B0 g3);
      [ exact (AnnDefEq_weak Hd1 Γ W) | exact (AnnDefEq_weak Hd2 Γ W)
      | exact (AnnTyping_weak Hta Γ W) | exact (AnnTyping_weak Htb Γ W) | exact Hde' ])
  | An_PiFst G0 D0 g0 A1 A2 rho B1 B2 Hd => fun Γ W => ltac:(
      apply (An_PiFst (Γ ++ G0) (D0 \u dom Γ) g0 A1 A2 rho B1 B2);
      exact (AnnDefEq_weak Hd Γ W))
  | An_PiSnd G0 D0 g1 g2 B1 a1 B2 a2 rho A1 A2 Hd1 Hd2 Hta1 Hta2 => fun Γ W => ltac:(
      apply (An_PiSnd (Γ ++ G0) (D0 \u dom Γ) g1 g2 B1 a1 B2 a2 rho A1 A2);
      [ exact (AnnDefEq_weak Hd1 Γ W) | exact (AnnDefEq_weak Hd2 Γ W)
      | exact (AnnTyping_weak Hta1 Γ W) | exact (AnnTyping_weak Hta2 Γ W) ])
  | An_CPiCong L G0 D0 g1 g3 phi1 B1 phi2 B3 B2 Hi Hd Heq Hta1 Hta2 Hta3 => fun Γ W => ltac:(
      assert (Hphi1 := AnnPropWff_weak (AnnTyping_cpi_inv Hta1) Γ W);
      assert (Hi' := AnnIso_weak Hi Γ W);
      apply (An_CPiCong (L \u dom (Γ ++ G0)) (Γ ++ G0) (D0 \u dom Γ) g1 g3 phi1 B1 phi2 B3 B2);
      [ exact Hi'
      | intros c Hc;
        assert (HcL : c \notin L) by fsetdec;
        assert (Hcd : c \notin dom (Γ ++ G0)) by fsetdec;
        assert (Wc : AnnCtx ((c ~ Co phi1) ++ (Γ ++ G0))) by (apply An_ConsCo; [ exact W | exact Hphi1 | exact Hcd ]);
        rewrite <- (@List.app_assoc (c ~ Co phi1) Γ G0) in Wc;
