      | exact Heq
      | exact (AnnTyping_weak Hta1 Γ W) | exact (AnnTyping_weak Hta2 Γ W) | exact (AnnTyping_weak Hta3 Γ W) ])
  | An_CAbsCong L G0 D0 g1 g3 g4 phi1 a1 phi2 a3 a2 B1 B0 B2 Hi Hd Heq Hta1 Hta2 Hta3 Hde => fun Γ W => ltac:(
      assert (Hphi1 := AnnPropWff_weak (AnnTyping_cabs_inv Hta1) Γ W);
