        assert (Wc : AnnCtx ((c ~ Co phi1) ++ (Γ ++ G0))) by (apply An_ConsCo; [ exact W | exact Hphi1 | exact Hcd ]);
        rewrite <- (@List.app_assoc (c ~ Co phi1) Γ G0) in Wc;
        exact (AnnDefEq_weak (Hd c HcL) ((c ~ Co phi1) ++ Γ) Wc)
      | exact Heq
      | exact (AnnTyping_weak Hta1 Γ W) | exact (AnnTyping_weak Hta2 Γ W) | exact (AnnTyping_weak Hta3 Γ W)
      | exact Hde' ])
  | An_CAppCong G0 D0 g1 g2 g3 a1 b1 a2 b2 a3 b3 A0 B0 g4 Hd1 Hd2 Hd3 Hta Htb Hde => fun Γ W => ltac:(
      assert (Hde' := AnnDefEq_weak Hde Γ W);
      rewrite (@dom_app Γ G0) in Hde';
      apply (An_CAppCong (Γ ++ G0) (D0 \u dom Γ) g1 g2 g3 a1 b1 a2 b2 a3 b3 A0 B0 g4);
      [ exact (AnnDefEq_weak Hd1 Γ W) | exact (AnnDefEq_weak Hd2 Γ W) | exact (AnnDefEq_weak Hd3 Γ W)
