   ===================================================================== *)

Fixpoint AnnTyping_weak (G:context) (a A:tm) (d:AnnTyping G a A) {struct d} :
  forall Γ, AnnCtx (Γ ++ G) -> AnnTyping (Γ ++ G) a A :=
  match d as d0 in AnnTyping G0 a0 A0 return (forall Γ, AnnCtx (Γ ++ G0) -> AnnTyping (Γ ++ G0) a0 A0) with
  | An_Star G0 HC => fun Γ W => An_Star (Γ ++ G0) W
  | An_Var G0 x A0 HC Hb => fun Γ W => An_Var (Γ ++ G0) x A0 W (binds_weak_tail Hb)
  | An_Pi L G0 rho A0 B0 Hbody HA => fun Γ W => ltac:(
      assert (HA' := @AnnTyping_weak G0 A0 a_Star HA Γ W);
      apply (An_Pi (L \u dom (Γ ++ G0)) (Γ ++ G0) rho A0 B0);
      [ intros x Hx;
        assert (HxL : x \notin L) by fsetdec;
        assert (Hxd : x \notin dom (Γ ++ G0)) by fsetdec;
        assert (Wx : AnnCtx ((x ~ Tm A0) ++ (Γ ++ G0))) by (apply An_ConsTm; [ exact W | exact HA' | exact Hxd ]);
        rewrite <- (@List.app_assoc (x ~ Tm A0) Γ G0) in Wx;
        exact (@AnnTyping_weak ((x ~ Tm A0) ++ G0) (open_tm_wrt_tm B0 (a_Var_f x)) a_Star (Hbody x HxL) ((x ~ Tm A0) ++ Γ) Wx)
      | exact HA' ])
  | An_Abs L G0 rho A0 a0 B0 HA Hbody HR => fun Γ W => ltac:(
      assert (HA' := @AnnTyping_weak G0 A0 a_Star HA Γ W);
      apply (An_Abs (L \u dom (Γ ++ G0)) (Γ ++ G0) rho A0 a0 B0);
      [ exact HA'
      | intros x Hx;
        assert (HxL : x \notin L) by fsetdec;
        assert (Hxd : x \notin dom (Γ ++ G0)) by fsetdec;
        assert (Wx : AnnCtx ((x ~ Tm A0) ++ (Γ ++ G0))) by (apply An_ConsTm; [ exact W | exact HA' | exact Hxd ]);
        rewrite <- (@List.app_assoc (x ~ Tm A0) Γ G0) in Wx;
        exact (@AnnTyping_weak ((x ~ Tm A0) ++ G0) (open_tm_wrt_tm a0 (a_Var_f x)) (open_tm_wrt_tm B0 (a_Var_f x)) (Hbody x HxL) ((x ~ Tm A0) ++ Γ) Wx)
      | intros x Hx; apply HR; fsetdec ])
  | An_App G0 b rho a0 B0 A0 Htyp Ha => fun Γ W => ltac:(
      apply (An_App (Γ ++ G0) b rho a0 B0 A0);
      [ exact (@AnnTyping_weak G0 b (a_Pi rho A0 B0) Htyp Γ W)
      | exact (@AnnTyping_weak G0 a0 A0 Ha Γ W) ])
  | An_Conv G0 a0 g B0 A0 Htyp Hde Hwf => fun Γ W => ltac:(
      assert (Hde_w := @AnnDefEq_weak G0 (dom G0) g A0 B0 Hde Γ W);
      assert (Hde_m := @AnnDefEq_mono (Γ ++ G0) (dom G0) g A0 B0 Hde_w (dom (Γ ++ G0)) (fun c H => dom_weak Γ G0 c H));
      apply (An_Conv (Γ ++ G0) a0 g B0 A0);
      [ exact (@AnnTyping_weak G0 a0 A0 Htyp Γ W) | exact Hde_m | exact (@AnnTyping_weak G0 B0 a_Star Hwf Γ W) ])
  | An_CPi L G0 phi B0 Hprop Hbody => fun Γ W => ltac:(
      assert (Hprop' := @AnnPropWff_weak G0 phi Hprop Γ W);
      apply (An_CPi (L \u dom (Γ ++ G0)) (Γ ++ G0) phi B0);
      [ exact Hprop'
      | intros c Hc;
        assert (HcL : c \notin L) by fsetdec;
        assert (Hcd : c \notin dom (Γ ++ G0)) by fsetdec;
        assert (Wc : AnnCtx ((c ~ Co phi) ++ (Γ ++ G0))) by (apply An_ConsCo; [ exact W | exact Hprop' | exact Hcd ]);
        rewrite <- (@List.app_assoc (c ~ Co phi) Γ G0) in Wc;
        exact (@AnnTyping_weak ((c ~ Co phi) ++ G0) (open_tm_wrt_co B0 (g_Var_f c)) a_Star (Hbody c HcL) ((c ~ Co phi) ++ Γ) Wc) ])
  | An_CAbs L G0 phi a0 B0 Hprop Hbody => fun Γ W => ltac:(
      assert (Hprop' := @AnnPropWff_weak G0 phi Hprop Γ W);
      apply (An_CAbs (L \u dom (Γ ++ G0)) (Γ ++ G0) phi a0 B0);
      [ exact Hprop'
      | intros c Hc;
        assert (HcL : c \notin L) by fsetdec;
        assert (Hcd : c \notin dom (Γ ++ G0)) by fsetdec;
        assert (Wc : AnnCtx ((c ~ Co phi) ++ (Γ ++ G0))) by (apply An_ConsCo; [ exact W | exact Hprop' | exact Hcd ]);
        rewrite <- (@List.app_assoc (c ~ Co phi) Γ G0) in Wc;
        exact (@AnnTyping_weak ((c ~ Co phi) ++ G0) (open_tm_wrt_co a0 (g_Var_f c)) (open_tm_wrt_co B0 (g_Var_f c)) (Hbody c HcL) ((c ~ Co phi) ++ Γ) Wc) ])
  | An_CApp G0 a1 g B0 a0 b0 A1 Htyp Hde => fun Γ W => ltac:(
      assert (Hde_w := @AnnDefEq_weak G0 (dom G0) g a0 b0 Hde Γ W);
      assert (Hde_m := @AnnDefEq_mono (Γ ++ G0) (dom G0) g a0 b0 Hde_w (dom (Γ ++ G0)) (fun c H => dom_weak Γ G0 c H));
      apply (An_CApp (Γ ++ G0) a1 g B0 a0 b0 A1);
      [ exact (@AnnTyping_weak G0 a1 (a_CPi (Eq a0 b0 A1) B0) Htyp Γ W) | exact Hde_m ])
  | An_Fam G0 F A0 a0 HC Hb Hty => fun Γ W => ltac:(
      apply (An_Fam (Γ ++ G0) F A0 a0); [ exact W | exact Hb | exact Hty ])
  end
with AnnPropWff_weak (G:context) (phi:constraint) (d:AnnPropWff G phi) {struct d} :
  forall Γ, AnnCtx (Γ ++ G) -> AnnPropWff (Γ ++ G) phi :=
  match d as d0 in AnnPropWff G0 p0 return (forall Γ, AnnCtx (Γ ++ G0) -> AnnPropWff (Γ ++ G0) p0) with
  | An_Wff G0 a0 b0 A0 B0 d1 d2 Heq => fun Γ W => ltac:(
      apply (An_Wff (Γ ++ G0) a0 b0 A0 B0);
      [ exact (@AnnTyping_weak G0 a0 A0 d1 Γ W) | exact (@AnnTyping_weak G0 b0 B0 d2 Γ W) | exact Heq ])
  end
with AnnIso_weak (G:context) (D:available_props) (g:co) (p1 p2:constraint)
    (d:AnnIso G D g p1 p2) {struct d} :
  forall Γ, AnnCtx (Γ ++ G) -> AnnIso (Γ ++ G) D g p1 p2 :=
  match d as d0 in AnnIso G0 D0 g0 p10 p20 return (forall Γ, AnnCtx (Γ ++ G0) -> AnnIso (Γ ++ G0) D0 g0 p10 p20) with
  | An_PropCong G0 D0 g1 A0 g2 A1 B1 A2 B2 Hd1 Hd2 Hp1 Hp2 => fun Γ W => ltac:(
      apply (An_PropCong (Γ ++ G0) D0 g1 A0 g2 A1 B1 A2 B2);
      [ exact (@AnnDefEq_weak G0 D0 g1 A1 A2 Hd1 Γ W) | exact (@AnnDefEq_weak G0 D0 g2 B1 B2 Hd2 Γ W)
      | exact (@AnnPropWff_weak G0 (Eq A1 B1 A0) Hp1 Γ W) | exact (@AnnPropWff_weak G0 (Eq A2 B2 A0) Hp2 Γ W) ])
  | An_CPiFst G0 D0 g0 phi1 phi2 A2 B2 Hd => fun Γ W => ltac:(
      apply (An_CPiFst (Γ ++ G0) D0 g0 phi1 phi2 A2 B2);
      exact (@AnnDefEq_weak G0 D0 g0 (a_CPi phi1 A2) (a_CPi phi2 B2) Hd Γ W))
  | An_IsoSym G0 D0 g0 phi2 phi1 Hi => fun Γ W => ltac:(
      apply (An_IsoSym (Γ ++ G0) D0 g0 phi2 phi1);
      exact (@AnnIso_weak G0 D0 g0 phi1 phi2 Hi Γ W))
  | An_IsoConv G0 D0 a1 a2 A0 a1' a2' B0 g0 Hd Hp1 Hp2 He1 He2 => fun Γ W => ltac:(
      apply (An_IsoConv (Γ ++ G0) D0 a1 a2 A0 a1' a2' B0 g0);
      [ exact (@AnnDefEq_weak G0 D0 g0 A0 B0 Hd Γ W)
      | exact (@AnnPropWff_weak G0 (Eq a1 a2 A0) Hp1 Γ W) | exact (@AnnPropWff_weak G0 (Eq a1' a2' B0) Hp2 Γ W)
      | exact He1 | exact He2 ])
  end
with AnnDefEq_weak (G:context) (D:available_props) (g:co) (a b:tm)
    (d:AnnDefEq G D g a b) {struct d} :
  forall Γ, AnnCtx (Γ ++ G) -> AnnDefEq (Γ ++ G) D g a b :=
  match d as d0 in AnnDefEq G0 D0 g0 a0 b0 return (forall Γ, AnnCtx (Γ ++ G0) -> AnnDefEq (Γ ++ G0) D0 g0 a0 b0) with
  | An_Assn G0 D0 c a0 b0 A0 HC Hb Hin => fun Γ W => ltac:(
      apply (An_Assn (Γ ++ G0) D0 c a0 b0 A0);
      [ exact W | exact (binds_weak_tail Hb) | exact Hin ])
  | An_Refl G0 D0 a0 A0 Ht => fun Γ W => ltac:(
      apply (An_Refl (Γ ++ G0) D0 a0 A0); exact (@AnnTyping_weak G0 a0 A0 Ht Γ W))
  | An_EraseEq G0 D0 a0 b0 g0 A0 B0 Hta Htb He Hd => fun Γ W => ltac:(
      assert (Hd_w := @AnnDefEq_weak G0 (dom G0) g0 A0 B0 Hd Γ W);
      assert (Hd_m := @AnnDefEq_mono (Γ ++ G0) (dom G0) g0 A0 B0 Hd_w (dom (Γ ++ G0)) (fun c H => dom_weak Γ G0 c H));
      apply (An_EraseEq (Γ ++ G0) D0 a0 b0 g0 A0 B0);
      [ exact (@AnnTyping_weak G0 a0 A0 Hta Γ W) | exact (@AnnTyping_weak G0 b0 B0 Htb Γ W) | exact He | exact Hd_m ])
  | An_Sym G0 D0 g0 a0 b0 B0 A0 g1 Htb Hta Hde Hd => fun Γ W => ltac:(
      assert (Hde_w := @AnnDefEq_weak G0 (dom G0) g1 B0 A0 Hde Γ W);
      assert (Hde_m := @AnnDefEq_mono (Γ ++ G0) (dom G0) g1 B0 A0 Hde_w (dom (Γ ++ G0)) (fun c H => dom_weak Γ G0 c H));
      apply (An_Sym (Γ ++ G0) D0 g0 a0 b0 B0 A0 g1);
      [ exact (@AnnTyping_weak G0 b0 B0 Htb Γ W) | exact (@AnnTyping_weak G0 a0 A0 Hta Γ W)
      | exact Hde_m | exact (@AnnDefEq_weak G0 D0 g0 b0 a0 Hd Γ W) ])
  | An_Trans G0 D0 g1 g2 a0 b0 a1 A0 A1 g3 Hd1 Hd2 Hta Hta1 Hde => fun Γ W => ltac:(
      assert (Hde_w := @AnnDefEq_weak G0 (dom G0) g3 A0 A1 Hde Γ W);
      assert (Hde_m := @AnnDefEq_mono (Γ ++ G0) (dom G0) g3 A0 A1 Hde_w (dom (Γ ++ G0)) (fun c H => dom_weak Γ G0 c H));
      apply (An_Trans (Γ ++ G0) D0 g1 g2 a0 b0 a1 A0 A1 g3);
      [ exact (@AnnDefEq_weak G0 D0 g1 a0 a1 Hd1 Γ W) | exact (@AnnDefEq_weak G0 D0 g2 a1 b0 Hd2 Γ W)
      | exact (@AnnTyping_weak G0 a0 A0 Hta Γ W) | exact (@AnnTyping_weak G0 a1 A1 Hta1 Γ W) | exact Hde_m ])
  | An_Beta G0 D0 a1 a2 B0 B1 Hta Htb He Hbeta => fun Γ W => ltac:(
      apply (An_Beta (Γ ++ G0) D0 a1 a2 B0 B1);
      [ exact (@AnnTyping_weak G0 a1 B0 Hta Γ W) | exact (@AnnTyping_weak G0 a2 B1 Htb Γ W) | exact He | exact Hbeta ])
  | An_PiCong L G0 D0 rho g1 g2 A1 B1 A2 B3 B2 Hd1 Hd2 Heq Hta1 Hta2 Hta3 => fun Γ W => ltac:(
      assert (HA1 := @AnnTyping_weak G0 A1 a_Star (AnnTyping_pi_inv Hta1) Γ W);
      apply (An_PiCong (L \u dom (Γ ++ G0)) (Γ ++ G0) D0 rho g1 g2 A1 B1 A2 B3 B2);
      [ exact (@AnnDefEq_weak G0 D0 g1 A1 A2 Hd1 Γ W)
      | intros x Hx;
        assert (HxL : x \notin L) by fsetdec;
        assert (Hxd : x \notin dom (Γ ++ G0)) by fsetdec;
        assert (Wx : AnnCtx ((x ~ Tm A1) ++ (Γ ++ G0))) by (apply An_ConsTm; [ exact W | exact HA1 | exact Hxd ]);
        rewrite <- (@List.app_assoc (x ~ Tm A1) Γ G0) in Wx;
        exact (@AnnDefEq_weak ((x ~ Tm A1) ++ G0) D0 (open_co_wrt_tm g2 (a_Var_f x)) (open_tm_wrt_tm B1 (a_Var_f x)) (open_tm_wrt_tm B2 (a_Var_f x)) (Hd2 x HxL) ((x ~ Tm A1) ++ Γ) Wx)
      | exact Heq
      | exact (@AnnTyping_weak G0 (a_Pi rho A1 B1) a_Star Hta1 Γ W)
      | exact (@AnnTyping_weak G0 (a_Pi rho A1 B2) a_Star Hta2 Γ W)
      | exact (@AnnTyping_weak G0 (a_Pi rho A2 B3) a_Star Hta3 Γ W) ])
  | An_AbsCong L G0 D0 rho g1 g2 A1 b1 A2 b3 b2 B0 Hd1 Hd2 Heq Hta1 Hta2 HR1 HR3 Hta => fun Γ W => ltac:(
      assert (HA1 := @AnnTyping_weak G0 A1 a_Star Hta1 Γ W);
      apply (An_AbsCong (L \u dom (Γ ++ G0)) (Γ ++ G0) D0 rho g1 g2 A1 b1 A2 b3 b2 B0);
      [ exact (@AnnDefEq_weak G0 D0 g1 A1 A2 Hd1 Γ W)
      | intros x Hx;
        assert (HxL : x \notin L) by fsetdec;
        assert (Hxd : x \notin dom (Γ ++ G0)) by fsetdec;
        assert (Wx : AnnCtx ((x ~ Tm A1) ++ (Γ ++ G0))) by (apply An_ConsTm; [ exact W | exact HA1 | exact Hxd ]);
        rewrite <- (@List.app_assoc (x ~ Tm A1) Γ G0) in Wx;
        exact (@AnnDefEq_weak ((x ~ Tm A1) ++ G0) D0 (open_co_wrt_tm g2 (a_Var_f x)) (open_tm_wrt_tm b1 (a_Var_f x)) (open_tm_wrt_tm b2 (a_Var_f x)) (Hd2 x HxL) ((x ~ Tm A1) ++ Γ) Wx)
      | exact Heq | exact HA1 | exact (@AnnTyping_weak G0 A2 a_Star Hta2 Γ W)
      | exact HR1 | exact HR3 | exact (@AnnTyping_weak G0 (a_Abs rho A1 b2) B0 Hta Γ W) ])
  | An_AppCong G0 D0 g1 rho g2 a1 a2 b1 b2 A0 B0 g3 Hd1 Hd2 Hta Htb Hde => fun Γ W => ltac:(
      assert (Hde_w := @AnnDefEq_weak G0 (dom G0) g3 A0 B0 Hde Γ W);
      assert (Hde_m := @AnnDefEq_mono (Γ ++ G0) (dom G0) g3 A0 B0 Hde_w (dom (Γ ++ G0)) (fun c H => dom_weak Γ G0 c H));
      apply (An_AppCong (Γ ++ G0) D0 g1 rho g2 a1 a2 b1 b2 A0 B0 g3);
      [ exact (@AnnDefEq_weak G0 D0 g1 a1 b1 Hd1 Γ W) | exact (@AnnDefEq_weak G0 D0 g2 a2 b2 Hd2 Γ W)
      | exact (@AnnTyping_weak G0 (a_App a1 rho a2) A0 Hta Γ W)
      | exact (@AnnTyping_weak G0 (a_App b1 rho b2) B0 Htb Γ W) | exact Hde_m ])
  | An_PiFst G0 D0 g0 A1 A2 rho B1 B2 Hd => fun Γ W => ltac:(
      apply (An_PiFst (Γ ++ G0) D0 g0 A1 A2 rho B1 B2);
      exact (@AnnDefEq_weak G0 D0 g0 (a_Pi rho A1 B1) (a_Pi rho A2 B2) Hd Γ W))
  | An_PiSnd G0 D0 g1 g2 B1 a1 B2 a2 rho A1 A2 Hd1 Hd2 Hta1 Hta2 => fun Γ W => ltac:(
      apply (An_PiSnd (Γ ++ G0) D0 g1 g2 B1 a1 B2 a2 rho A1 A2);
      [ exact (@AnnDefEq_weak G0 D0 g1 (a_Pi rho A1 B1) (a_Pi rho A2 B2) Hd1 Γ W)
      | exact (@AnnDefEq_weak G0 D0 g2 a1 a2 Hd2 Γ W)
      | exact (@AnnTyping_weak G0 a1 A1 Hta1 Γ W) | exact (@AnnTyping_weak G0 a2 A2 Hta2 Γ W) ])
  | An_CPiCong L G0 D0 g1 g3 phi1 B1 phi2 B3 B2 Hi Hd Heq Hta1 Hta2 Hta3 => fun Γ W => ltac:(
      assert (Hphi1 := @AnnPropWff_weak G0 phi1 (AnnTyping_cpi_inv Hta1) Γ W);
      apply (An_CPiCong (L \u dom (Γ ++ G0)) (Γ ++ G0) D0 g1 g3 phi1 B1 phi2 B3 B2);
      [ exact (@AnnIso_weak G0 D0 g1 phi1 phi2 Hi Γ W)
      | intros c Hc;
        assert (HcL : c \notin L) by fsetdec;
        assert (Hcd : c \notin dom (Γ ++ G0)) by fsetdec;
        assert (Wc : AnnCtx ((c ~ Co phi1) ++ (Γ ++ G0))) by (apply An_ConsCo; [ exact W | exact Hphi1 | exact Hcd ]);
        rewrite <- (@List.app_assoc (c ~ Co phi1) Γ G0) in Wc;
        exact (@AnnDefEq_weak ((c ~ Co phi1) ++ G0) D0 (open_co_wrt_co g3 (g_Var_f c)) (open_tm_wrt_co B1 (g_Var_f c)) (open_tm_wrt_co B2 (g_Var_f c)) (Hd c HcL) ((c ~ Co phi1) ++ Γ) Wc)
      | exact Heq
      | exact (@AnnTyping_weak G0 (a_CPi phi1 B1) a_Star Hta1 Γ W)
      | exact (@AnnTyping_weak G0 (a_CPi phi2 B3) a_Star Hta2 Γ W)
      | exact (@AnnTyping_weak G0 (a_CPi phi1 B2) a_Star Hta3 Γ W) ])
  | An_CAbsCong L G0 D0 g1 g3 g4 phi1 a1 phi2 a3 a2 B1 B0 B2 Hi Hd Heq Hta1 Hta2 Hta3 Hde => fun Γ W => ltac:(
      assert (Hphi1 := @AnnPropWff_weak G0 phi1 (AnnTyping_cabs_inv Hta1) Γ W);
      assert (Hde_w := @AnnDefEq_weak G0 (dom G0) g4 (a_CPi phi1 B1) (a_CPi phi2 B2) Hde Γ W);
      assert (Hde_m := @AnnDefEq_mono (Γ ++ G0) (dom G0) g4 (a_CPi phi1 B1) (a_CPi phi2 B2) Hde_w (dom (Γ ++ G0)) (fun c H => dom_weak Γ G0 c H));
      apply (An_CAbsCong (L \u dom (Γ ++ G0)) (Γ ++ G0) D0 g1 g3 g4 phi1 a1 phi2 a3 a2 B1 B0 B2);
      [ exact (@AnnIso_weak G0 D0 g1 phi1 phi2 Hi Γ W)
      | intros c Hc;
        assert (HcL : c \notin L) by fsetdec;
        assert (Hcd : c \notin dom (Γ ++ G0)) by fsetdec;
        assert (Wc : AnnCtx ((c ~ Co phi1) ++ (Γ ++ G0))) by (apply An_ConsCo; [ exact W | exact Hphi1 | exact Hcd ]);
        rewrite <- (@List.app_assoc (c ~ Co phi1) Γ G0) in Wc;
        exact (@AnnDefEq_weak ((c ~ Co phi1) ++ G0) D0 (open_co_wrt_co g3 (g_Var_f c)) (open_tm_wrt_co a1 (g_Var_f c)) (open_tm_wrt_co a2 (g_Var_f c)) (Hd c HcL) ((c ~ Co phi1) ++ Γ) Wc)
      | exact Heq
      | exact (@AnnTyping_weak G0 (a_CAbs phi1 a1) (a_CPi phi1 B1) Hta1 Γ W)
      | exact (@AnnTyping_weak G0 (a_CAbs phi1 a2) B0 Hta2 Γ W)
      | exact (@AnnTyping_weak G0 (a_CAbs phi2 a3) (a_CPi phi2 B2) Hta3 Γ W)
      | exact Hde_m ])
  | An_CAppCong G0 D0 g1 g2 g3 a1 b1 a2 b2 a3 b3 A0 B0 g4 Hd1 Hd2 Hd3 Hta Htb Hde => fun Γ W => ltac:(
      assert (Hde_w := @AnnDefEq_weak G0 (dom G0) g4 A0 B0 Hde Γ W);
      assert (Hde_m := @AnnDefEq_mono (Γ ++ G0) (dom G0) g4 A0 B0 Hde_w (dom (Γ ++ G0)) (fun c H => dom_weak Γ G0 c H));
      assert (Hd2_w := @AnnDefEq_weak G0 (dom G0) g2 a2 b2 Hd2 Γ W);
      assert (Hd2_m := @AnnDefEq_mono (Γ ++ G0) (dom G0) g2 a2 b2 Hd2_w (dom (Γ ++ G0)) (fun c H => dom_weak Γ G0 c H));
      assert (Hd3_w := @AnnDefEq_weak G0 (dom G0) g3 a3 b3 Hd3 Γ W);
      assert (Hd3_m := @AnnDefEq_mono (Γ ++ G0) (dom G0) g3 a3 b3 Hd3_w (dom (Γ ++ G0)) (fun c H => dom_weak Γ G0 c H));
      apply (An_CAppCong (Γ ++ G0) D0 g1 g2 g3 a1 b1 a2 b2 a3 b3 A0 B0 g4);
      [ exact (@AnnDefEq_weak G0 D0 g1 a1 b1 Hd1 Γ W) | exact Hd2_m | exact Hd3_m
      | exact (@AnnTyping_weak G0 (a_CApp a1 g2) A0 Hta Γ W)
      | exact (@AnnTyping_weak G0 (a_CApp b1 g3) B0 Htb Γ W) | exact Hde_m ])
  | An_CPiSnd G0 D0 g1 g2 g3 B1 B2 a a' A b b' B Hd1 Hd2 Hd3 => fun Γ W => ltac:(
      assert (Hd2_w := @AnnDefEq_weak G0 (dom G0) g2 a a' Hd2 Γ W);
      assert (Hd2_m := @AnnDefEq_mono (Γ ++ G0) (dom G0) g2 a a' Hd2_w (dom (Γ ++ G0)) (fun c H => dom_weak Γ G0 c H));
      assert (Hd3_w := @AnnDefEq_weak G0 (dom G0) g3 b b' Hd3 Γ W);
      assert (Hd3_m := @AnnDefEq_mono (Γ ++ G0) (dom G0) g3 b b' Hd3_w (dom (Γ ++ G0)) (fun c H => dom_weak Γ G0 c H));
      apply (An_CPiSnd (Γ ++ G0) D0 g1 g2 g3 B1 B2 a a' A b b' B);
      [ exact (@AnnDefEq_weak G0 D0 g1 (a_CPi (Eq a a' A) B1) (a_CPi (Eq b b' B) B2) Hd1 Γ W)
      | exact Hd2_m | exact Hd3_m ])
  | An_Cast G0 D0 g1 g2 b b' a a' A B Hd Hi => fun Γ W => ltac:(
      apply (An_Cast (Γ ++ G0) D0 g1 g2 b b' a a' A B);
      [ exact (@AnnDefEq_weak G0 D0 g1 a a' Hd Γ W)
      | exact (@AnnIso_weak G0 D0 g2 (Eq a a' A) (Eq b b' B) Hi Γ W) ])
  | An_IsoSnd G0 D0 g0 A B a a' b b' Hi => fun Γ W => ltac:(
      apply (An_IsoSnd (Γ ++ G0) D0 g0 A B a a' b b');
      exact (@AnnIso_weak G0 D0 g0 (Eq a a' A) (Eq b b' B) Hi Γ W))
  end.
EOF
