(* =====================================================================
   Weakening, inserting Γ just above G (context Δ ++ Γ ++ G).
   ===================================================================== *)

Fixpoint AnnTyping_weak (Δ G:context) (a A:tm) (d:AnnTyping (Δ ++ G) a A) {struct d} :
  forall Γ, AnnCtx (Δ ++ Γ ++ G) -> AnnTyping (Δ ++ Γ ++ G) a A :=
  match d as d0 in AnnTyping H0 a0 A0 return (forall Γ, AnnCtx (Δ ++ Γ ++ G) -> AnnTyping (Δ ++ Γ ++ G) a0 A0) with
  | An_Star Hc HC => fun Γ W => An_Star (Δ ++ Γ ++ G) W
  | An_Var Hc x A0 HC Hb => fun Γ W => An_Var (Δ ++ Γ ++ G) x A0 W (@binds_weak_tail Δ (Γ ++ G) x (Tm A0) Hb)
  | An_Pi L Hc rho A0 B0 Hbody HA => fun Γ W => ltac:(
      assert (HA' := @AnnTyping_weak Δ G A0 a_Star HA Γ W);
      apply (An_Pi (L \u dom (Δ ++ Γ ++ G)) (Δ ++ Γ ++ G) rho A0 B0);
      [ intros x Hx;
        assert (HxL : x \notin L) by fsetdec;
        assert (Hxd : x \notin dom (Δ ++ Γ ++ G)) by fsetdec;
        assert (Wx : AnnCtx (((x ~ Tm A0) ++ Δ) ++ Γ ++ G)) by (apply An_ConsTm; [ exact W | exact HA' | exact Hxd ]);
        exact (@AnnTyping_weak ((x ~ Tm A0) ++ Δ) G (open_tm_wrt_tm B0 (a_Var_f x)) a_Star (Hbody x HxL) Γ Wx)
      | exact HA' ])
  | An_Abs L Hc rho A0 a0 B0 HA Hbody HR => fun Γ W => ltac:(
      assert (HA' := @AnnTyping_weak Δ G A0 a_Star HA Γ W);
      apply (An_Abs (L \u dom (Δ ++ Γ ++ G)) (Δ ++ Γ ++ G) rho A0 a0 B0);
      [ exact HA'
      | intros x Hx;
        assert (HxL : x \notin L) by fsetdec;
        assert (Hxd : x \notin dom (Δ ++ Γ ++ G)) by fsetdec;
        assert (Wx : AnnCtx (((x ~ Tm A0) ++ Δ) ++ Γ ++ G)) by (apply An_ConsTm; [ exact W | exact HA' | exact Hxd ]);
        exact (@AnnTyping_weak ((x ~ Tm A0) ++ Δ) G (open_tm_wrt_tm a0 (a_Var_f x)) (open_tm_wrt_tm B0 (a_Var_f x)) (Hbody x HxL) Γ Wx)
      | intros x Hx; apply HR; fsetdec ])
  | An_App Hc b rho a0 B0 A0 Htyp Ha => fun Γ W => ltac:(
      apply (An_App (Δ ++ Γ ++ G) b rho a0 B0 A0);
      [ exact (@AnnTyping_weak Δ G b (a_Pi rho A0 B0) Htyp Γ W)
      | exact (@AnnTyping_weak Δ G a0 A0 Ha Γ W) ])
  | An_Conv Hc a0 g B0 A0 Htyp Hde Hwf => fun Γ W => ltac:(
      assert (Hde_w := @AnnDefEq_weak Δ G (dom (Δ ++ G)) g A0 B0 Hde Γ W);
      assert (Hde_m := @AnnDefEq_mono (Δ ++ Γ ++ G) (dom (Δ ++ G)) g A0 B0 Hde_w (dom (Δ ++ Γ ++ G)) (fun c H => dom_weak Δ G c H));
      apply (An_Conv (Δ ++ Γ ++ G) a0 g B0 A0);
      [ exact (@AnnTyping_weak Δ G a0 A0 Htyp Γ W) | exact Hde_m | exact (@AnnTyping_weak Δ G B0 a_Star Hwf Γ W) ])
  | An_CPi L Hc phi B0 Hprop Hbody => fun Γ W => ltac:(
      assert (Hprop' := @AnnPropWff_weak Δ G phi Hprop Γ W);
      apply (An_CPi (L \u dom (Δ ++ Γ ++ G)) (Δ ++ Γ ++ G) phi B0);
      [ exact Hprop'
      | intros c Hc';
        assert (HcL : c \notin L) by fsetdec;
        assert (Hcd : c \notin dom (Δ ++ Γ ++ G)) by fsetdec;
        assert (Wc : AnnCtx (((c ~ Co phi) ++ Δ) ++ Γ ++ G)) by (apply An_ConsCo; [ exact W | exact Hprop' | exact Hcd ]);
        exact (@AnnTyping_weak ((c ~ Co phi) ++ Δ) G (open_tm_wrt_co B0 (g_Var_f c)) a_Star (Hbody c HcL) Γ Wc) ])
  | An_CAbs L Hc phi a0 B0 Hprop Hbody => fun Γ W => ltac:(
      assert (Hprop' := @AnnPropWff_weak Δ G phi Hprop Γ W);
      apply (An_CAbs (L \u dom (Δ ++ Γ ++ G)) (Δ ++ Γ ++ G) phi a0 B0);
      [ exact Hprop'
      | intros c Hc';
        assert (HcL : c \notin L) by fsetdec;
        assert (Hcd : c \notin dom (Δ ++ Γ ++ G)) by fsetdec;
        assert (Wc : AnnCtx (((c ~ Co phi) ++ Δ) ++ Γ ++ G)) by (apply An_ConsCo; [ exact W | exact Hprop' | exact Hcd ]);
        exact (@AnnTyping_weak ((c ~ Co phi) ++ Δ) G (open_tm_wrt_co a0 (g_Var_f c)) (open_tm_wrt_co B0 (g_Var_f c)) (Hbody c HcL) Γ Wc) ])
  | An_CApp Hc a1 g B0 a0 b0 A1 Htyp Hde => fun Γ W => ltac:(
      assert (Hde_w := @AnnDefEq_weak Δ G (dom (Δ ++ G)) g a0 b0 Hde Γ W);
      assert (Hde_m := @AnnDefEq_mono (Δ ++ Γ ++ G) (dom (Δ ++ G)) g a0 b0 Hde_w (dom (Δ ++ Γ ++ G)) (fun c H => dom_weak Δ G c H));
      apply (An_CApp (Δ ++ Γ ++ G) a1 g B0 a0 b0 A1);
      [ exact (@AnnTyping_weak Δ G a1 (a_CPi (Eq a0 b0 A1) B0) Htyp Γ W) | exact Hde_m ])
  | An_Fam Hc F A0 a0 HC Hb Hty => fun Γ W => ltac:(
      apply (An_Fam (Δ ++ Γ ++ G) F A0 a0); [ exact W | exact Hb | exact Hty ])
  end
with AnnPropWff_weak (Δ G:context) (phi:constraint) (d:AnnPropWff (Δ ++ G) phi) {struct d} :
  forall Γ, AnnCtx (Δ ++ Γ ++ G) -> AnnPropWff (Δ ++ Γ ++ G) phi :=
  match d as d0 in AnnPropWff H0 p0 return (forall Γ, AnnCtx (Δ ++ Γ ++ G) -> AnnPropWff (Δ ++ Γ ++ G) p0) with
  | An_Wff Hc a0 b0 A0 B0 d1 d2 Heq => fun Γ W => ltac:(
      apply (An_Wff (Δ ++ Γ ++ G) a0 b0 A0 B0);
      [ exact (@AnnTyping_weak Δ G a0 A0 d1 Γ W) | exact (@AnnTyping_weak Δ G b0 B0 d2 Γ W) | exact Heq ])
  end
with AnnIso_weak (Δ G:context) (D:available_props) (g:co) (p1 p2:constraint)
    (d:AnnIso (Δ ++ G) D g p1 p2) {struct d} :
  forall Γ, AnnCtx (Δ ++ Γ ++ G) -> AnnIso (Δ ++ Γ ++ G) D g p1 p2 :=
  match d as d0 in AnnIso H0 D0 g0 p10 p20 return (forall Γ, AnnCtx (Δ ++ Γ ++ G) -> AnnIso (Δ ++ Γ ++ G) D0 g0 p10 p20) with
  | An_PropCong Hc D0 g1 A0 g2 A1 B1 A2 B2 Hd1 Hd2 Hp1 Hp2 => fun Γ W => ltac:(
      apply (An_PropCong (Δ ++ Γ ++ G) D0 g1 A0 g2 A1 B1 A2 B2);
      [ exact (@AnnDefEq_weak Δ G D0 g1 A1 A2 Hd1 Γ W) | exact (@AnnDefEq_weak Δ G D0 g2 B1 B2 Hd2 Γ W)
      | exact (@AnnPropWff_weak Δ G (Eq A1 B1 A0) Hp1 Γ W) | exact (@AnnPropWff_weak Δ G (Eq A2 B2 A0) Hp2 Γ W) ])
  | An_CPiFst Hc D0 g0 phi1 phi2 A2 B2 Hd => fun Γ W => ltac:(
      apply (An_CPiFst (Δ ++ Γ ++ G) D0 g0 phi1 phi2 A2 B2);
      exact (@AnnDefEq_weak Δ G D0 g0 (a_CPi phi1 A2) (a_CPi phi2 B2) Hd Γ W))
  | An_IsoSym Hc D0 g0 phi2 phi1 Hi => fun Γ W => ltac:(
      apply (An_IsoSym (Δ ++ Γ ++ G) D0 g0 phi2 phi1);
      exact (@AnnIso_weak Δ G D0 g0 phi1 phi2 Hi Γ W))
  | An_IsoConv Hc D0 a1 a2 A0 a1' a2' B0 g0 Hd Hp1 Hp2 He1 He2 => fun Γ W => ltac:(
      apply (An_IsoConv (Δ ++ Γ ++ G) D0 a1 a2 A0 a1' a2' B0 g0);
      [ exact (@AnnDefEq_weak Δ G D0 g0 A0 B0 Hd Γ W)
      | exact (@AnnPropWff_weak Δ G (Eq a1 a2 A0) Hp1 Γ W) | exact (@AnnPropWff_weak Δ G (Eq a1' a2' B0) Hp2 Γ W)
      | exact He1 | exact He2 ])
  end
with AnnDefEq_weak (Δ G:context) (D:available_props) (g:co) (a b:tm)
    (d:AnnDefEq (Δ ++ G) D g a b) {struct d} :
  forall Γ, AnnCtx (Δ ++ Γ ++ G) -> AnnDefEq (Δ ++ Γ ++ G) D g a b :=
  match d as d0 in AnnDefEq H0 D0 g0 a0 b0 return (forall Γ, AnnCtx (Δ ++ Γ ++ G) -> AnnDefEq (Δ ++ Γ ++ G) D0 g0 a0 b0) with
  | An_Assn Hc D0 c a0 b0 A0 HC Hb Hin => fun Γ W => ltac:(
      apply (An_Assn (Δ ++ Γ ++ G) D0 c a0 b0 A0);
      [ exact W | exact (@binds_weak_tail Δ (Γ ++ G) c (Co (Eq a0 b0 A0)) Hb) | exact Hin ])
  | An_Refl Hc D0 a0 A0 Ht => fun Γ W => ltac:(
      apply (An_Refl (Δ ++ Γ ++ G) D0 a0 A0); exact (@AnnTyping_weak Δ G a0 A0 Ht Γ W))
  | An_EraseEq Hc D0 a0 b0 g0 A0 B0 Hta Htb He Hd => fun Γ W => ltac:(
      assert (Hd_w := @AnnDefEq_weak Δ G (dom (Δ ++ G)) g0 A0 B0 Hd Γ W);
      assert (Hd_m := @AnnDefEq_mono (Δ ++ Γ ++ G) (dom (Δ ++ G)) g0 A0 B0 Hd_w (dom (Δ ++ Γ ++ G)) (fun c H => dom_weak Δ G c H));
      apply (An_EraseEq (Δ ++ Γ ++ G) D0 a0 b0 g0 A0 B0);
      [ exact (@AnnTyping_weak Δ G a0 A0 Hta Γ W) | exact (@AnnTyping_weak Δ G b0 B0 Htb Γ W) | exact He | exact Hd_m ])
  | An_Sym Hc D0 g0 a0 b0 B0 A0 g1 Htb Hta Hde Hd => fun Γ W => ltac:(
      assert (Hde_w := @AnnDefEq_weak Δ G (dom (Δ ++ G)) g1 B0 A0 Hde Γ W);
      assert (Hde_m := @AnnDefEq_mono (Δ ++ Γ ++ G) (dom (Δ ++ G)) g1 B0 A0 Hde_w (dom (Δ ++ Γ ++ G)) (fun c H => dom_weak Δ G c H));
      apply (An_Sym (Δ ++ Γ ++ G) D0 g0 a0 b0 B0 A0 g1);
      [ exact (@AnnTyping_weak Δ G b0 B0 Htb Γ W) | exact (@AnnTyping_weak Δ G a0 A0 Hta Γ W)
      | exact Hde_m | exact (@AnnDefEq_weak Δ G D0 g0 b0 a0 Hd Γ W) ])
  | An_Trans Hc D0 g1 g2 a0 b0 a1 A0 A1 g3 Hd1 Hd2 Hta Hta1 Hde => fun Γ W => ltac:(
      assert (Hde_w := @AnnDefEq_weak Δ G (dom (Δ ++ G)) g3 A0 A1 Hde Γ W);
      assert (Hde_m := @AnnDefEq_mono (Δ ++ Γ ++ G) (dom (Δ ++ G)) g3 A0 A1 Hde_w (dom (Δ ++ Γ ++ G)) (fun c H => dom_weak Δ G c H));
      apply (An_Trans (Δ ++ Γ ++ G) D0 g1 g2 a0 b0 a1 A0 A1 g3);
      [ exact (@AnnDefEq_weak Δ G D0 g1 a0 a1 Hd1 Γ W) | exact (@AnnDefEq_weak Δ G D0 g2 a1 b0 Hd2 Γ W)
      | exact (@AnnTyping_weak Δ G a0 A0 Hta Γ W) | exact (@AnnTyping_weak Δ G a1 A1 Hta1 Γ W) | exact Hde_m ])
  | An_Beta Hc D0 a1 a2 B0 B1 Hta Htb He Hbeta => fun Γ W => ltac:(
      apply (An_Beta (Δ ++ Γ ++ G) D0 a1 a2 B0 B1);
      [ exact (@AnnTyping_weak Δ G a1 B0 Hta Γ W) | exact (@AnnTyping_weak Δ G a2 B1 Htb Γ W) | exact He | exact Hbeta ])
  | An_PiCong L Hc D0 rho g1 g2 A1 B1 A2 B3 B2 Hd1 Hd2 Heq Hta1 Hta2 Hta3 => fun Γ W => ltac:(
      assert (HA1 := @AnnTyping_weak Δ G A1 a_Star (AnnTyping_pi_inv Hta1) Γ W);
      apply (An_PiCong (L \u dom (Δ ++ Γ ++ G)) (Δ ++ Γ ++ G) D0 rho g1 g2 A1 B1 A2 B3 B2);
      [ exact (@AnnDefEq_weak Δ G D0 g1 A1 A2 Hd1 Γ W)
      | intros x Hx;
        assert (HxL : x \notin L) by fsetdec;
        assert (Hxd : x \notin dom (Δ ++ Γ ++ G)) by fsetdec;
        assert (Wx : AnnCtx (((x ~ Tm A1) ++ Δ) ++ Γ ++ G)) by (apply An_ConsTm; [ exact W | exact HA1 | exact Hxd ]);
        exact (@AnnDefEq_weak ((x ~ Tm A1) ++ Δ) G D0 (open_co_wrt_tm g2 (a_Var_f x)) (open_tm_wrt_tm B1 (a_Var_f x)) (open_tm_wrt_tm B2 (a_Var_f x)) (Hd2 x HxL) Γ Wx)
      | exact Heq
      | exact (@AnnTyping_weak Δ G (a_Pi rho A1 B1) a_Star Hta1 Γ W)
      | exact (@AnnTyping_weak Δ G (a_Pi rho A1 B2) a_Star Hta2 Γ W)
      | exact (@AnnTyping_weak Δ G (a_Pi rho A2 B3) a_Star Hta3 Γ W) ])
  | An_AbsCong L Hc D0 rho g1 g2 A1 b1 A2 b3 b2 B0 Hd1 Hd2 Heq Hta1 Hta2 HR1 HR3 Hta => fun Γ W => ltac:(
      assert (HA1 := @AnnTyping_weak Δ G A1 a_Star Hta1 Γ W);
      apply (An_AbsCong (L \u dom (Δ ++ Γ ++ G)) (Δ ++ Γ ++ G) D0 rho g1 g2 A1 b1 A2 b3 b2 B0);
      [ exact (@AnnDefEq_weak Δ G D0 g1 A1 A2 Hd1 Γ W)
      | intros x Hx;
        assert (HxL : x \notin L) by fsetdec;
        assert (Hxd : x \notin dom (Δ ++ Γ ++ G)) by fsetdec;
        assert (Wx : AnnCtx (((x ~ Tm A1) ++ Δ) ++ Γ ++ G)) by (apply An_ConsTm; [ exact W | exact HA1 | exact Hxd ]);
        exact (@AnnDefEq_weak ((x ~ Tm A1) ++ Δ) G D0 (open_co_wrt_tm g2 (a_Var_f x)) (open_tm_wrt_tm b1 (a_Var_f x)) (open_tm_wrt_tm b2 (a_Var_f x)) (Hd2 x HxL) Γ Wx)
      | exact Heq | exact HA1 | exact (@AnnTyping_weak Δ G A2 a_Star Hta2 Γ W)
      | exact HR1 | exact HR3 | exact (@AnnTyping_weak Δ G (a_Abs rho A1 b2) B0 Hta Γ W) ])
  | An_AppCong Hc D0 g1 rho g2 a1 a2 b1 b2 A0 B0 g3 Hd1 Hd2 Hta Htb Hde => fun Γ W => ltac:(
      assert (Hde_w := @AnnDefEq_weak Δ G (dom (Δ ++ G)) g3 A0 B0 Hde Γ W);
      assert (Hde_m := @AnnDefEq_mono (Δ ++ Γ ++ G) (dom (Δ ++ G)) g3 A0 B0 Hde_w (dom (Δ ++ Γ ++ G)) (fun c H => dom_weak Δ G c H));
      apply (An_AppCong (Δ ++ Γ ++ G) D0 g1 rho g2 a1 a2 b1 b2 A0 B0 g3);
      [ exact (@AnnDefEq_weak Δ G D0 g1 a1 b1 Hd1 Γ W) | exact (@AnnDefEq_weak Δ G D0 g2 a2 b2 Hd2 Γ W)
      | exact (@AnnTyping_weak Δ G (a_App a1 rho a2) A0 Hta Γ W)
      | exact (@AnnTyping_weak Δ G (a_App b1 rho b2) B0 Htb Γ W) | exact Hde_m ])
  | An_PiFst Hc D0 g0 A1 A2 rho B1 B2 Hd => fun Γ W => ltac:(
      apply (An_PiFst (Δ ++ Γ ++ G) D0 g0 A1 A2 rho B1 B2);
      exact (@AnnDefEq_weak Δ G D0 g0 (a_Pi rho A1 B1) (a_Pi rho A2 B2) Hd Γ W))
  | An_PiSnd Hc D0 g1 g2 B1 a1 B2 a2 rho A1 A2 Hd1 Hd2 Hta1 Hta2 => fun Γ W => ltac:(
      apply (An_PiSnd (Δ ++ Γ ++ G) D0 g1 g2 B1 a1 B2 a2 rho A1 A2);
      [ exact (@AnnDefEq_weak Δ G D0 g1 (a_Pi rho A1 B1) (a_Pi rho A2 B2) Hd1 Γ W)
      | exact (@AnnDefEq_weak Δ G D0 g2 a1 a2 Hd2 Γ W)
      | exact (@AnnTyping_weak Δ G a1 A1 Hta1 Γ W) | exact (@AnnTyping_weak Δ G a2 A2 Hta2 Γ W) ])
  | An_CPiCong L Hc D0 g1 g3 phi1 B1 phi2 B3 B2 Hi Hd Heq Hta1 Hta2 Hta3 => fun Γ W => ltac:(
      assert (Hphi1 := @AnnPropWff_weak Δ G phi1 (AnnTyping_cpi_inv Hta1) Γ W);
      apply (An_CPiCong (L \u dom (Δ ++ Γ ++ G)) (Δ ++ Γ ++ G) D0 g1 g3 phi1 B1 phi2 B3 B2);
      [ exact (@AnnIso_weak Δ G D0 g1 phi1 phi2 Hi Γ W)
      | intros c Hc';
        assert (HcL : c \notin L) by fsetdec;
        assert (Hcd : c \notin dom (Δ ++ Γ ++ G)) by fsetdec;
        assert (Wc : AnnCtx (((c ~ Co phi1) ++ Δ) ++ Γ ++ G)) by (apply An_ConsCo; [ exact W | exact Hphi1 | exact Hcd ]);
        exact (@AnnDefEq_weak ((c ~ Co phi1) ++ Δ) G D0 (open_co_wrt_co g3 (g_Var_f c)) (open_tm_wrt_co B1 (g_Var_f c)) (open_tm_wrt_co B2 (g_Var_f c)) (Hd c HcL) Γ Wc)
      | exact Heq
      | exact (@AnnTyping_weak Δ G (a_CPi phi1 B1) a_Star Hta1 Γ W)
      | exact (@AnnTyping_weak Δ G (a_CPi phi2 B3) a_Star Hta2 Γ W)
      | exact (@AnnTyping_weak Δ G (a_CPi phi1 B2) a_Star Hta3 Γ W) ])
  | An_CAbsCong L Hc D0 g1 g3 g4 phi1 a1 phi2 a3 a2 B1 B0 B2 Hi Hd Heq Hta1 Hta2 Hta3 Hde => fun Γ W => ltac:(
      assert (Hphi1 := @AnnPropWff_weak Δ G phi1 (AnnTyping_cabs_inv Hta1) Γ W);
      assert (Hde_w := @AnnDefEq_weak Δ G (dom (Δ ++ G)) g4 (a_CPi phi1 B1) (a_CPi phi2 B2) Hde Γ W);
      assert (Hde_m := @AnnDefEq_mono (Δ ++ Γ ++ G) (dom (Δ ++ G)) g4 (a_CPi phi1 B1) (a_CPi phi2 B2) Hde_w (dom (Δ ++ Γ ++ G)) (fun c H => dom_weak Δ G c H));
      apply (An_CAbsCong (L \u dom (Δ ++ Γ ++ G)) (Δ ++ Γ ++ G) D0 g1 g3 g4 phi1 a1 phi2 a3 a2 B1 B0 B2);
      [ exact (@AnnIso_weak Δ G D0 g1 phi1 phi2 Hi Γ W)
      | intros c Hc';
        assert (HcL : c \notin L) by fsetdec;
        assert (Hcd : c \notin dom (Δ ++ Γ ++ G)) by fsetdec;
        assert (Wc : AnnCtx (((c ~ Co phi1) ++ Δ) ++ Γ ++ G)) by (apply An_ConsCo; [ exact W | exact Hphi1 | exact Hcd ]);
        exact (@AnnDefEq_weak ((c ~ Co phi1) ++ Δ) G D0 (open_co_wrt_co g3 (g_Var_f c)) (open_tm_wrt_co a1 (g_Var_f c)) (open_tm_wrt_co a2 (g_Var_f c)) (Hd c HcL) Γ Wc)
      | exact Heq
      | exact (@AnnTyping_weak Δ G (a_CAbs phi1 a1) (a_CPi phi1 B1) Hta1 Γ W)
      | exact (@AnnTyping_weak Δ G (a_CAbs phi1 a2) B0 Hta2 Γ W)
      | exact (@AnnTyping_weak Δ G (a_CAbs phi2 a3) (a_CPi phi2 B2) Hta3 Γ W)
      | exact Hde_m ])
  | An_CAppCong Hc D0 g1 g2 g3 a1 b1 a2 b2 a3 b3 A0 B0 g4 Hd1 Hd2 Hd3 Hta Htb Hde => fun Γ W => ltac:(
      assert (Hde_w := @AnnDefEq_weak Δ G (dom (Δ ++ G)) g4 A0 B0 Hde Γ W);
      assert (Hde_m := @AnnDefEq_mono (Δ ++ Γ ++ G) (dom (Δ ++ G)) g4 A0 B0 Hde_w (dom (Δ ++ Γ ++ G)) (fun c H => dom_weak Δ G c H));
      assert (Hd2_w := @AnnDefEq_weak Δ G (dom (Δ ++ G)) g2 a2 b2 Hd2 Γ W);
      assert (Hd2_m := @AnnDefEq_mono (Δ ++ Γ ++ G) (dom (Δ ++ G)) g2 a2 b2 Hd2_w (dom (Δ ++ Γ ++ G)) (fun c H => dom_weak Δ G c H));
      assert (Hd3_w := @AnnDefEq_weak Δ G (dom (Δ ++ G)) g3 a3 b3 Hd3 Γ W);
      assert (Hd3_m := @AnnDefEq_mono (Δ ++ Γ ++ G) (dom (Δ ++ G)) g3 a3 b3 Hd3_w (dom (Δ ++ Γ ++ G)) (fun c H => dom_weak Δ G c H));
      apply (An_CAppCong (Δ ++ Γ ++ G) D0 g1 g2 g3 a1 b1 a2 b2 a3 b3 A0 B0 g4);
      [ exact (@AnnDefEq_weak Δ G D0 g1 a1 b1 Hd1 Γ W) | exact Hd2_m | exact Hd3_m
      | exact (@AnnTyping_weak Δ G (a_CApp a1 g2) A0 Hta Γ W)
      | exact (@AnnTyping_weak Δ G (a_CApp b1 g3) B0 Htb Γ W) | exact Hde_m ])
  | An_CPiSnd Hc D0 g1 g2 g3 B1 B2 a a' A b b' B Hd1 Hd2 Hd3 => fun Γ W => ltac:(
      assert (Hd2_w := @AnnDefEq_weak Δ G (dom (Δ ++ G)) g2 a a' Hd2 Γ W);
      assert (Hd2_m := @AnnDefEq_mono (Δ ++ Γ ++ G) (dom (Δ ++ G)) g2 a a' Hd2_w (dom (Δ ++ Γ ++ G)) (fun c H => dom_weak Δ G c H));
      assert (Hd3_w := @AnnDefEq_weak Δ G (dom (Δ ++ G)) g3 b b' Hd3 Γ W);
      assert (Hd3_m := @AnnDefEq_mono (Δ ++ Γ ++ G) (dom (Δ ++ G)) g3 b b' Hd3_w (dom (Δ ++ Γ ++ G)) (fun c H => dom_weak Δ G c H));
      apply (An_CPiSnd (Δ ++ Γ ++ G) D0 g1 g2 g3 B1 B2 a a' A b b' B);
      [ exact (@AnnDefEq_weak Δ G D0 g1 (a_CPi (Eq a a' A) B1) (a_CPi (Eq b b' B) B2) Hd1 Γ W)
      | exact Hd2_m | exact Hd3_m ])
  | An_Cast Hc D0 g1 g2 b b' a a' A B Hd Hi => fun Γ W => ltac:(
      apply (An_Cast (Δ ++ Γ ++ G) D0 g1 g2 b b' a a' A B);
      [ exact (@AnnDefEq_weak Δ G D0 g1 a a' Hd Γ W)
      | exact (@AnnIso_weak Δ G D0 g2 (Eq a a' A) (Eq b b' B) Hi Γ W) ])
  | An_IsoSnd Hc D0 g0 A B a a' b b' Hi => fun Γ W => ltac:(
      apply (An_IsoSnd (Δ ++ Γ ++ G) D0 g0 A B a a' b b');
      exact (@AnnIso_weak Δ G D0 g0 (Eq a a' A) (Eq b b' B) Hi Γ W))
  end.
EOF
