Require Import Language Dev0 CompTest Occ Syn FixTP FixCO Ren RenOpen Erase Ctx Subst Pclosed.
From Stdlib Require Import Lia List.
Set Implicit Arguments.

(* =====================================================================
   Substituting a freshly opened variable: if x does not occur in t,
   then  subst x v (open t x) = open t v.
   ===================================================================== *)

Fixpoint os_tm (t:tm) {struct t} :
  forall (k:nat) (x:atom) (v:tm), x \notin occ_tm t ->
    subst_tm x v (open_tm_wrt_tm_rec k (a_Var_f x) t) =
    open_tm_wrt_tm_rec k v t :=
  match t as t0 return (forall (k:nat) (x:atom) (v:tm), x \notin occ_tm t0 ->
    subst_tm x v (open_tm_wrt_tm_rec k (a_Var_f x) t0) =
    open_tm_wrt_tm_rec k v t0) with
  | a_Star => fun k x v H => eq_refl
  | a_Var_b m => fun k x v H => ltac:(
      cbn [open_tm_wrt_tm_rec subst_tm];
      destruct (lt_eq_lt_dec m k) as [[E|E]|E]; cbn [open_tm_wrt_tm_rec subst_tm]; reflexivity)
  | a_Var_f z => fun k x v H => ltac:(
      cbn [open_tm_wrt_tm_rec subst_tm occ_tm] in *;
      destruct (KeySetFacts.eq_dec z x) as [E|E];
      [ exfalso; apply H; fsetdec
      | reflexivity ])
  | a_Abs rho A b => fun k x v H => ltac:(
      cbn [occ_tm] in H; destruct H as [HA Hb];
      cbn [open_tm_wrt_tm_rec subst_tm]; f_equal;
      [ exact (os_tm A k x v HA) | exact (os_tm b (S k) x v Hb) ])
  | a_UAbs rho b => fun k x v H => ltac:(
      cbn [occ_tm] in H;
      cbn [open_tm_wrt_tm_rec subst_tm]; f_equal;
      exact (os_tm b (S k) x v H))
  | a_App a rho b => fun k x v H => ltac:(
      cbn [occ_tm] in H; destruct H as [HA Hb];
      cbn [open_tm_wrt_tm_rec subst_tm]; f_equal;
      [ exact (os_tm a k x v HA) | exact (os_tm b k x v Hb) ])
  | a_Fam F => fun k x v H => eq_refl
  | a_Const T => fun k x v H => eq_refl
  | a_Pi rho A B => fun k x v H => ltac:(
      cbn [occ_tm] in H; destruct H as [HA HB];
      cbn [open_tm_wrt_tm_rec subst_tm]; f_equal;
      [ exact (os_tm A k x v HA) | exact (os_tm B (S k) x v HB) ])
  | a_Conv a g => fun k x v H => ltac:(
      cbn [occ_tm] in H; destruct H as [Ha Hg];
      cbn [open_tm_wrt_tm_rec subst_tm]; f_equal;
      [ exact (os_tm a k x v Ha) | exact (os_co g k x v Hg) ])
  | a_CPi phi B => fun k x v H => ltac:(
      cbn [occ_tm] in H; destruct H as [Hp HB];
      cbn [open_tm_wrt_tm_rec subst_tm]; f_equal;
      [ exact (os_con phi k x v Hp) | exact (os_tm B k x v HB) ])
  | a_CAbs phi b => fun k x v H => ltac:(
      cbn [occ_tm] in H; destruct H as [Hp Hb];
      cbn [open_tm_wrt_tm_rec subst_tm]; f_equal;
      [ exact (os_con phi k x v Hp) | exact (os_tm b k x v Hb) ])
  | a_UCAbs b => fun k x v H => ltac:(
      cbn [occ_tm] in H;
      cbn [open_tm_wrt_tm_rec subst_tm]; f_equal;
      exact (os_tm b k x v H))
  | a_CApp a g => fun k x v H => ltac:(
      cbn [occ_tm] in H; destruct H as [Ha Hg];
      cbn [open_tm_wrt_tm_rec subst_tm]; f_equal;
      [ exact (os_tm a k x v Ha) | exact (os_co g k x v Hg) ])
  | a_Bullet => fun k x v H => eq_refl
  | a_DataCon K => fun k x v H => eq_refl
  | a_Case a bs => fun k x v H => ltac:(
      cbn [occ_tm] in H; destruct H as [Ha Hb];
      cbn [open_tm_wrt_tm_rec subst_tm]; f_equal;
      [ exact (os_tm a k x v Ha) | exact (os_brs bs k x v Hb) ])
  end
with os_brs (bs:brs) {struct bs} :
  forall (k:nat) (x:atom) (v:tm), x \notin occ_brs bs ->
    subst_brs_tm x v (open_brs_wrt_tm_rec k (a_Var_f x) bs) =
    open_brs_wrt_tm_rec k v bs :=
  match bs as s0 return (forall (k:nat) (x:atom) (v:tm), x \notin occ_brs s0 ->
    subst_brs_tm x v (open_brs_wrt_tm_rec k (a_Var_f x) s0) =
    open_brs_wrt_tm_rec k v s0) with
  | br_None => fun k x v H => eq_refl
  | br_One K a b => fun k x v H => ltac:(
      cbn [occ_brs] in H; destruct H as [Ha Hb];
      cbn [open_brs_wrt_tm_rec subst_brs_tm]; f_equal;
      [ exact (os_tm a k x v Ha) | exact (os_brs b k x v Hb) ])
  end
with os_con (p:constraint) {struct p} :
  forall (k:nat) (x:atom) (v:tm), x \notin occ_con p ->
    subst_con_tm x v (open_constraint_wrt_tm_rec k (a_Var_f x) p) =
    open_constraint_wrt_tm_rec k v p :=
  match p as s0 return (forall (k:nat) (x:atom) (v:tm), x \notin occ_con s0 ->
    subst_con_tm x v (open_constraint_wrt_tm_rec k (a_Var_f x) s0) =
    open_constraint_wrt_tm_rec k v s0) with
  | Eq a b A => fun k x v H => ltac:(
      cbn [occ_con] in H; destruct H as [Ha [Hb HA]];
      cbn [open_constraint_wrt_tm_rec subst_con_tm]; f_equal;
      [ exact (os_tm a k x v Ha)
      | exact (os_tm b k x v Hb)
      | exact (os_tm A k x v HA) ])
  end
with os_co (g:co) {struct g} :
  forall (k:nat) (x:atom) (v:tm), x \notin occ_co g ->
    subst_co_tm x v (open_co_wrt_tm_rec k (a_Var_f x) g) =
    open_co_wrt_tm_rec k v g :=
  match g as s0 return (forall (k:nat) (x:atom) (v:tm), x \notin occ_co s0 ->
    subst_co_tm x v (open_co_wrt_tm_rec k (a_Var_f x) s0) =
    open_co_wrt_tm_rec k v s0) with
  | g_Triv => fun k x v H => eq_refl
  | g_Var_b m => fun k x v H => eq_refl
  | g_Var_f c => fun k x v H => eq_refl
  | g_Beta a b => fun k x v H => ltac:(
      cbn [occ_co] in H; destruct H as [Ha Hb];
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      [ exact (os_tm a k x v Ha) | exact (os_tm b k x v Hb) ])
  | g_Refl a => fun k x v H => ltac:(
      cbn [occ_co] in H;
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      exact (os_tm a k x v H))
  | g_Refl2 a b h => fun k x v H => ltac:(
      cbn [occ_co] in H; destruct H as [Ha [Hb Hh]];
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      [ exact (os_tm a k x v Ha)
      | exact (os_tm b k x v Hb)
      | exact (os_co h k x v Hh) ])
  | g_Sym h => fun k x v H => ltac:(
      cbn [occ_co] in H;
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      exact (os_co h k x v H))
  | g_Trans g1 g2 => fun k x v H => ltac:(
      cbn [occ_co] in H; destruct H as [H1 H2];
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      [ exact (os_co g1 k x v H1) | exact (os_co g2 k x v H2) ])
  | g_PiCong rho g1 g2 => fun k x v H => ltac:(
      cbn [occ_co] in H; destruct H as [H1 H2];
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      [ exact (os_co g1 k x v H1) | exact (os_co g2 (S k) x v H2) ])
  | g_AbsCong rho g1 g2 => fun k x v H => ltac:(
      cbn [occ_co] in H; destruct H as [H1 H2];
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      [ exact (os_co g1 k x v H1) | exact (os_co g2 (S k) x v H2) ])
  | g_AppCong g1 rho g2 => fun k x v H => ltac:(
      cbn [occ_co] in H; destruct H as [H1 H2];
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      [ exact (os_co g1 k x v H1) | exact (os_co g2 k x v H2) ])
  | g_PiFst h => fun k x v H => ltac:(
      cbn [occ_co] in H;
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      exact (os_co h k x v H))
  | g_CPiFst h => fun k x v H => ltac:(
      cbn [occ_co] in H;
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      exact (os_co h k x v H))
  | g_IsoSnd h => fun k x v H => ltac:(
      cbn [occ_co] in H;
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      exact (os_co h k x v H))
  | g_PiSnd g1 g2 => fun k x v H => ltac:(
      cbn [occ_co] in H; destruct H as [H1 H2];
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      [ exact (os_co g1 k x v H1) | exact (os_co g2 k x v H2) ])
  | g_CPiCong g1 g3 => fun k x v H => ltac:(
      cbn [occ_co] in H; destruct H as [H1 H2];
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      [ exact (os_co g1 k x v H1) | exact (os_co g3 k x v H2) ])
  | g_CAbsCong g1 g3 g4 => fun k x v H => ltac:(
      cbn [occ_co] in H; destruct H as [H1 [H2 H3]];
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      [ exact (os_co g1 k x v H1)
      | exact (os_co g3 k x v H2)
      | exact (os_co g4 k x v H3) ])
  | g_CAppCong h g1 g2 => fun k x v H => ltac:(
      cbn [occ_co] in H; destruct H as [H1 [H2 H3]];
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      [ exact (os_co h k x v H1)
      | exact (os_co g1 k x v H2)
      | exact (os_co g2 k x v H3) ])
  | g_CPiSnd h g1 g2 => fun k x v H => ltac:(
      cbn [occ_co] in H; destruct H as [H1 [H2 H3]];
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      [ exact (os_co h k x v H1)
      | exact (os_co g1 k x v H2)
      | exact (os_co g2 k x v H3) ])
  | g_Cast g1 g2 => fun k x v H => ltac:(
      cbn [occ_co] in H; destruct H as [H1 H2];
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      [ exact (os_co g1 k x v H1) | exact (os_co g2 k x v H2) ])
  | g_EqCong g1 A g2 => fun k x v H => ltac:(
      cbn [occ_co] in H; destruct H as [H1 [HA H2]];
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      [ exact (os_co g1 k x v H1)
      | exact (os_tm A k x v HA)
      | exact (os_co g2 k x v H2) ])
  | g_IsoConv phi1 phi2 h => fun k x v H => ltac:(
      cbn [occ_co] in H; destruct H as [H1 [H2 Hh]];
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      [ exact (os_con phi1 k x v H1)
      | exact (os_con phi2 k x v H2)
      | exact (os_co h k x v Hh) ])
  | g_Eta a => fun k x v H => ltac:(
      cbn [occ_co] in H;
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      exact (os_tm a k x v H))
  | g_Left h h' => fun k x v H => ltac:(
      cbn [occ_co] in H; destruct H as [H1 H2];
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      [ exact (os_co h k x v H1) | exact (os_co h' k x v H2) ])
  | g_Right h h' => fun k x v H => ltac:(
      cbn [occ_co] in H; destruct H as [H1 H2];
      cbn [open_co_wrt_tm_rec subst_co_tm]; f_equal;
      [ exact (os_co h k x v H1) | exact (os_co h' k x v H2) ])
  end.

