(* =====================================================================
   Coercion substitution at a freshly opened coercion variable:
   if c does not occur in t, then
     subst_co c g (open t c) = open t g
   (the substituted coercion must be closed for de Bruijn indices).
   ===================================================================== *)

Fixpoint goc_tm (t:tm) {struct t} :
  forall (k:nat) (c:atom) (g:co), c \notin occ_tm t -> pclosed_co 0 0 g ->
    subst_tm_co c g (open_tm_wrt_co_rec k (g_Var_f c) t) =
    open_tm_wrt_co_rec k g t :=
  match t as t0 return (forall (k:nat) (c:atom) (g:co), c \notin occ_tm t0 -> pclosed_co 0 0 g ->
    subst_tm_co c g (open_tm_wrt_co_rec k (g_Var_f c) t0) =
    open_tm_wrt_co_rec k g t0) with
  | a_Star => fun k c g H Hg => eq_refl
  | a_Var_b m => fun k c g H Hg => eq_refl
  | a_Var_f z => fun k c g H Hg => eq_refl
  | a_Abs rho A b => fun k c g H Hg => ltac:(
      cbn [occ_tm] in H;
      cbn [open_tm_wrt_co_rec subst_tm_co]; f_equal;
      [ exact (goc_tm A k c g ltac:(fsetdec) Hg)
      | exact (goc_tm b k c g ltac:(fsetdec) Hg) ])
  | a_UAbs rho b => fun k c g H Hg => ltac:(
      cbn [occ_tm] in H;
      cbn [open_tm_wrt_co_rec subst_tm_co]; f_equal;
      exact (goc_tm b k c g H Hg))
  | a_App a rho b => fun k c g H Hg => ltac:(
      cbn [occ_tm] in H;
      cbn [open_tm_wrt_co_rec subst_tm_co]; f_equal;
      [ exact (goc_tm a k c g ltac:(fsetdec) Hg)
      | exact (goc_tm b k c g ltac:(fsetdec) Hg) ])
  | a_Fam F => fun k c g H Hg => eq_refl
  | a_Const T => fun k c g H Hg => eq_refl
  | a_Pi rho A B => fun k c g H Hg => ltac:(
      cbn [occ_tm] in H;
      cbn [open_tm_wrt_co_rec subst_tm_co]; f_equal;
      [ exact (goc_tm A k c g ltac:(fsetdec) Hg)
