  | a_CPi phi B => fun k c g H Hg => ltac:(
      cbn [occ_tm] in H;
      cbn [open_tm_wrt_co_rec subst_tm_co]; f_equal;
      [ exact (goc_con phi k c g ltac:(fsetdec) Hg)
      | exact (goc_tm B (S k) c g ltac:(fsetdec) Hg) ])
  | a_CAbs phi b => fun k c g H Hg => ltac:(
      cbn [occ_tm] in H;
      cbn [open_tm_wrt_co_rec subst_tm_co]; f_equal;
      [ exact (goc_con phi k c g ltac:(fsetdec) Hg)
      | exact (goc_tm b (S k) c g ltac:(fsetdec) Hg) ])
  | a_UCAbs b => fun k c g H Hg => ltac:(
      cbn [occ_tm] in H;
