Require Import Language Dev0 CompTest Occ Syn FixTP FixCO Ren RenOpen Erase Ctx Subst Pclosed.
From Stdlib Require Import Lia List.
Set Implicit Arguments.

Fixpoint epc_tm (t:tm) {struct t} :
  forall (nt nc:nat), pclosed_tm nt nc t -> pclosed_tm nt nc (erase_tm t) :=
  match t as t0 return (forall (nt nc:nat), pclosed_tm nt nc t0 -> pclosed_tm nt nc (erase_tm t0)) with
  | a_Star => fun nt nc H => I
  | a_Var_b n => fun nt nc H => ltac:(cbn [pclosed_tm] in H; cbn [erase_tm pclosed_tm]; exact H)
  | a_Var_f x => fun nt nc H => I
  | a_Abs rho A b => fun nt nc H => ltac:(
      cbn [pclosed_tm] in H; destruct H as [HA Hb];
      cbn [erase_tm pclosed_tm]; exact (epc_tm b (S nt) nc Hb))
  | a_UAbs rho b => fun nt nc H => ltac:(
      cbn [pclosed_tm] in H; cbn [erase_tm pclosed_tm]; exact (epc_tm b (S nt) nc H))
  | a_App a rho b => fun nt nc H => ltac:(
      cbn [pclosed_tm] in H; destruct H as [Ha Hb];
      destruct rho; cbn [erase_tm pclosed_tm];
