  | a_Const T => fun nt nc H => I
  | a_Pi rho A B => fun nt nc H => ltac:(
      cbn [pclosed_tm] in H; destruct H as [HA HB];
      cbn [erase_tm pclosed_tm]; split;
      try (exact (epc_tm A nt nc HA));
      try (exact (epc_tm B (S nt) nc HB)))
  | a_Conv a g => fun nt nc H => ltac:(
      cbn [pclosed_tm] in H; destruct H as [Ha Hg];
      cbn [erase_tm]; exact (epc_tm a nt nc Ha))
  | a_CPi phi B => fun nt nc H => ltac:(
      cbn [pclosed_tm] in H; destruct H as [Hp HB];
      cbn [erase_tm pclosed_tm]; split;
      try (exact (epc_con phi nt nc Hp));
      try (exact (epc_tm B nt (S nc) HB)))
