    pclosed_con nt nc (subst_con_tm x v p0)) with
  | Eq a b A => fun x v nt nc H Hv => ltac:(
      cbn [pclosed_con subst_con_tm] in H;
      destruct H as [Ha [Hb HA]];
      cbn [pclosed_con subst_con_tm]; split;
      [ exact (pc_subst_tm a x v nt nc Ha Hv)
      | split;
        [ exact (pc_subst_tm b x v nt nc Hb Hv)
        | exact (pc_subst_tm A x v nt nc HA Hv) ] ])
  end
with pc_subst_co (g:co) {struct g} :
  forall (x:atom) (v:tm) (nt nc:nat),
    pclosed_co nt nc g -> pclosed_tm 0 0 v ->
    pclosed_co nt nc (subst_co_tm x v g) :=
  match g as g0 return (forall (x:atom) (v:tm) (nt nc:nat),
    pclosed_co nt nc g0 -> pclosed_tm 0 0 v ->
    pclosed_co nt nc (subst_co_tm x v g0)) with
  | g_Triv => fun x v nt nc H Hv => I
  | g_Var_b n => fun x v nt nc H Hv => H
  | g_Var_f c => fun x v nt nc H Hv => I
  | g_Beta a b => fun x v nt nc H Hv => ltac:(
      cbn [pclosed_co subst_co_tm] in H; destruct H as [Ha Hb];
      cbn [pclosed_co subst_co_tm]; split;
      [ exact (pc_subst_tm a x v nt nc Ha Hv)
      | exact (pc_subst_tm b x v nt nc Hb Hv) ])
  | g_Refl a => fun x v nt nc H Hv => ltac:(
      cbn [pclosed_co subst_co_tm] in H; cbn [pclosed_co subst_co_tm];
      exact (pc_subst_tm a x v nt nc H Hv))
  | g_Refl2 a b h => fun x v nt nc H Hv => ltac:(
      cbn [pclosed_co subst_co_tm] in H; destruct H as [Ha [Hb Hh]];
      cbn [pclosed_co subst_co_tm]; split;
      [ exact (pc_subst_tm a x v nt nc Ha Hv)
      | split;
        [ exact (pc_subst_tm b x v nt nc Hb Hv)
        | exact (pc_subst_co h x v nt nc Hh Hv) ] ])
  | g_Sym h => fun x v nt nc H Hv => ltac:(
      cbn [pclosed_co subst_co_tm] in H; cbn [pclosed_co subst_co_tm];
      exact (pc_subst_co h x v nt nc H Hv))
  | g_Trans g1 g2 => fun x v nt nc H Hv => ltac:(
      cbn [pclosed_co subst_co_tm] in H; destruct H as [H1 H2];
      cbn [pclosed_co subst_co_tm]; split;
      [ exact (pc_subst_co g1 x v nt nc H1 Hv)
      | exact (pc_subst_co g2 x v nt nc H2 Hv) ])
  | g_PiCong rho g1 g2 => fun x v nt nc H Hv => ltac:(
      cbn [pclosed_co subst_co_tm] in H; destruct H as [H1 H2];
      cbn [pclosed_co subst_co_tm]; split;
      [ exact (pc_subst_co g1 x v nt nc H1 Hv)
      | exact (pc_subst_co g2 x v (S nt) nc H2 Hv) ])
  | g_AbsCong rho g1 g2 => fun x v nt nc H Hv => ltac:(
      cbn [pclosed_co subst_co_tm] in H; destruct H as [H1 H2];
      cbn [pclosed_co subst_co_tm]; split;
      [ exact (pc_subst_co g1 x v nt nc H1 Hv)
      | exact (pc_subst_co g2 x v (S nt) nc H2 Hv) ])
  | g_AppCong g1 rho g2 => fun x v nt nc H Hv => ltac:(
      cbn [pclosed_co subst_co_tm] in H; destruct H as [H1 H2];
      cbn [pclosed_co subst_co_tm]; split;
      [ exact (pc_subst_co g1 x v nt nc H1 Hv)
      | exact (pc_subst_co g2 x v nt nc H2 Hv) ])
  | g_PiFst h => fun x v nt nc H Hv => ltac:(
      cbn [pclosed_co subst_co_tm] in H; cbn [pclosed_co subst_co_tm];
      exact (pc_subst_co h x v nt nc H Hv))
  | g_CPiFst h => fun x v nt nc H Hv => ltac:(
      cbn [pclosed_co subst_co_tm] in H; cbn [pclosed_co subst_co_tm];
      exact (pc_subst_co h x v nt nc H Hv))
  | g_IsoSnd h => fun x v nt nc H Hv => ltac:(
