  | g_CPiSnd h g1 g2 => fun x v nt nc H Hv => ltac:(
      cbn [pclosed_co subst_co_tm] in H; destruct H as [Hh [H1 H2]];
      cbn [pclosed_co subst_co_tm]; split;
      [ exact (pc_subst_co h x v nt nc Hh Hv)
