Fixpoint U_typing (G:context) (aa A:tm) (d:AnnTyping G aa A) {struct d} :
  forall A', AnnTyping G aa A' -> erase_tm A = erase_tm A' :=
  match d as d0 in AnnTyping G0 a0 A0 return (forall A', AnnTyping G0 a0 A' -> erase_tm A0 = erase_tm A') with
  | An_Star G0 HC => fun A' d' => ltac:(inversion d'; subst; reflexivity)
  | An_Var G0 x A0 HC Hb => fun A' d' => ltac:(inversion d'; subst;
        assert (Tm A0 = Tm A') as Hu by (eapply AnnCtx_binds_unique; eauto);
        injection Hu as HA; rewrite HA; reflexivity)
  | An_Pi L G0 rho A0 B0 Hbody HA => fun A' d' => ltac:(inversion d'; subst; reflexivity)
  | An_Abs L G0 rho A0 ab B0 HA Hbody HR => fun A' d' => ltac:(
      inversion d'; subst; cbn [erase_tm];
      match goal with
      | Hbody' : forall x, x \notin ?Lx -> AnnTyping ((x ~ Tm A0) ++ G0) (open_tm_wrt_tm ab (a_Var_f x)) (open_tm_wrt_tm ?Bv (a_Var_f x)) |- a_Pi rho (erase_tm A0) (erase_tm B0) = a_Pi rho (erase_tm A0) (erase_tm ?Tv) =>
          destruct (atom_fresh (L \u Lx \u occ_tm (erase_tm B0) \u occ_tm (erase_tm Bv))) as [z Hz];
          assert (Hz1 : z \notin L) by fsetdec;
          assert (Hz2 : z \notin Lx) by fsetdec;
          pose proof (@U_typing (z ~ Tm A0 ++ G0) (open_tm_wrt_tm ab (a_Var_f z)) (open_tm_wrt_tm B0 (a_Var_f z)) (Hbody z Hz1) (open_tm_wrt_tm Bv (a_Var_f z)) (Hbody' z Hz2)) as He;
          rewrite erase_open_tm' in He; rewrite erase_open_tm' in He;
          assert (erase_tm B0 = erase_tm Bv) as HB by (eapply open_inj_tm; eauto);
          rewrite HB; reflexivity
      end)
  | An_App G0 b rho ab B0 A0 Htyp Ha => fun A' d' => ltac:(
      inversion d'; subst;
      match goal with
      | H : AnnTyping G0 b (a_Pi rho ?A1 ?B1) |- erase_tm (open_tm_wrt_tm B0 ab) = erase_tm (open_tm_wrt_tm ?Tv ab) =>
          pose proof (@U_typing G0 b (a_Pi rho A0 B0) Htyp (a_Pi rho A1 B1) H) as He;
          cbn [erase_tm] in He; assert (erase_tm B0 = erase_tm B1) as HB by (injection He; auto);
          rewrite erase_open_tm'; rewrite erase_open_tm'; rewrite HB; reflexivity
      end)
  | An_Conv G0 ab g B0 A0 Htyp Hde Hwf => fun A' d' => ltac:(
      inversion d'; subst;
      match goal with
      | H : AnnDefEq G0 (dom G0) g ?A1 ?B1 |- erase_tm B0 = erase_tm ?Tv =>
          pose proof (@U_defeq G0 (dom G0) g A0 B0 Hde G0 (dom G0) A1 B1 (CE_refl G0) H) as He;
          destruct He as [_ HB]; exact HB
      end)
  | An_CPi L G0 phi B0 Hprop Hbody => fun A' d' => ltac:(inversion d'; subst; reflexivity)
  | An_CAbs L G0 phi ab B0 Hprop Hbody => fun A' d' => ltac:(
      inversion d'; subst; cbn [erase_tm];
      match goal with
      | Hbody' : forall x, x \notin ?Lx -> AnnTyping ((x ~ Co phi) ++ G0) (open_tm_wrt_co ab (g_Var_f x)) (open_tm_wrt_co ?Bv (g_Var_f x)) |- a_CPi (erase_constraint phi) (erase_tm B0) = a_CPi (erase_constraint phi) (erase_tm ?Tv) =>
          destruct (atom_fresh (L \u Lx)) as [z Hz];
          assert (Hz1 : z \notin L) by fsetdec;
          assert (Hz2 : z \notin Lx) by fsetdec;
          pose proof (@U_typing (z ~ Co phi ++ G0) (open_tm_wrt_co ab (g_Var_f z)) (open_tm_wrt_co B0 (g_Var_f z)) (Hbody z Hz1) (open_tm_wrt_co Bv (g_Var_f z)) (Hbody' z Hz2)) as He;
          rewrite erase_openco_tm' in He; rewrite erase_openco_tm' in He;
          rewrite He; reflexivity
      end)
  | An_CApp G0 a1 g B0 ab b A1 Htyp Hde => fun A' d' => ltac:(
      inversion d'; subst;
      match goal with
      | H : AnnTyping G0 a1 (a_CPi ?phi ?B1) |- erase_tm (open_tm_wrt_co B0 g) = erase_tm (open_tm_wrt_co ?Tv g) =>
          pose proof (@U_typing G0 a1 (a_CPi (Eq ab b A1) B0) Htyp (a_CPi phi B1) H) as He;
          cbn [erase_tm] in He;
          assert (erase_tm B0 = erase_tm B1) as HB by (injection He; auto);
          rewrite erase_openco_tm'; rewrite erase_openco_tm'; rewrite HB; reflexivity
      end)
  | An_Fam G0 F A0 ab HC Hb Hty => fun A' d' => ltac:(
      inversion d'; subst;
      assert (A0 = FixTy) as HA0 by (eapply an_toplevel_binds; eauto);
      assert (A' = FixTy) as HA1 by (eapply an_toplevel_binds; eauto);
      rewrite HA0, HA1; reflexivity)
  end
with U_prop (G:context) (phi:constraint) (d:AnnPropWff G phi) {struct d} : True :=
  match d as d0 in AnnPropWff G0 p0 return True with
  | An_Wff G0 a b A B d1 d2 Heq => I
  end

with U_iso (G:context) (D:available_props) (g:co) (p1 p2:constraint) (d:AnnIso G D g p1 p2) {struct d} :
  forall G' D' p1' p2', CE G G' -> AnnIso G' D' g p1' p2' ->
    erase_constraint p1 = erase_constraint p1' /\ erase_constraint p2 = erase_constraint p2' :=
  match d as d0 in AnnIso G0 D0 g0 p10 p20 return (forall G' D' p1' p2', CE G0 G' -> AnnIso G' D' g0 p1' p2' ->
    erase_constraint p10 = erase_constraint p1' /\ erase_constraint p20 = erase_constraint p2') with
  | An_PropCong G0 D0 g1 A0 g2 A1 B1 A2 B2 Hd1 Hd2 Hp1 Hp2 => fun G' D' p1' p2' Hce d' => ltac:(
      inversion d' as [ qG1 qD1 qg1 qA0 qg2 qA1 qB1 qA2 qB2 qHd1 qHd2 qHp1 qHp2
        | qG1 qD1 qg1 qp1 qp2 qA2 qB2 qHd1
        | qG1 qD1 qg1 qp2 qp1 qHi
        | qG1 qD1 qa1 qa2 qA qa1' qa2' qB qg qHd qHp1 qHp2 qHe1 qHe2 ];
      subst;
      match type of qHd1 with AnnDefEq ?GG ?DD ?gg ?e1 ?e2 =>
        destruct (@U_defeq G0 D0 g1 A1 A2 Hd1 G' DD e1 e2 Hce qHd1) as [HA1 HA2] end;
      match type of qHd2 with AnnDefEq ?GG ?DD ?gg ?e1 ?e2 =>
        destruct (@U_defeq G0 D0 g2 B1 B2 Hd2 G' DD e1 e2 Hce qHd2) as [HB1 HB2] end;
      split; cbn [erase_constraint]; f_equal; auto)
  | An_CPiFst G0 D0 g0 phi1 phi2 A2 B2 Hd => fun G' D' p1' p2' Hce d' => ltac:(
      inversion d' as [ qG1 qD1 qg1 qA0 qg2 qA1 qB1 qA2 qB2 qHd1 qHd2 qHp1 qHp2
        | qG1 qD1 qg1 qp1 qp2 qA2 qB2 qHd1
        | qG1 qD1 qg1 qp2 qp1 qHi
        | qG1 qD1 qa1 qa2 qA qa1' qa2' qB qg qHd qHp1 qHp2 qHe1 qHe2 ];
      subst;
      match type of qHd1 with AnnDefEq ?GG ?DD ?gg (a_CPi ?e1 ?AA) (a_CPi ?e2 ?BB) =>
        destruct (@U_defeq G0 D0 g0 (a_CPi phi1 A2) (a_CPi phi2 B2) Hd G' DD (a_CPi e1 AA) (a_CPi e2 BB) Hce qHd1) as [H1 H2];
        cbn [erase_tm] in H1, H2;
        assert (erase_constraint phi1 = erase_constraint e1) as E1 by congruence;
        assert (erase_constraint phi2 = erase_constraint e2) as E2 by congruence;
        split; auto
      end)
  | An_IsoSym G0 D0 g0 phi2 phi1 Hi => fun G' D' p1' p2' Hce d' => ltac:(
      inversion d' as [ qG1 qD1 qg1 qA0 qg2 qA1 qB1 qA2 qB2 qHd1 qHd2 qHp1 qHp2
        | qG1 qD1 qg1 qp1 qp2 qA2 qB2 qHd1
        | qG1 qD1 qg1 qp2 qp1 qHi
        | qG1 qD1 qa1 qa2 qA qa1' qa2' qB qg qHd qHp1 qHp2 qHe1 qHe2 ];
      subst;
      match type of qHi with AnnIso ?GG ?DD qg1 ?e1 ?e2 =>
        destruct (@U_iso G0 D0 g0 phi1 phi2 Hi G' DD e1 e2 Hce qHi) as [H1 H2]
      end; split; auto)
  | An_IsoConv G0 D0 a1 a2 A0 a1' a2' B0 g0 Hd Hp1 Hp2 He1 He2 => fun G' D' p1' p2' Hce d' => ltac:(
      inversion d' as [ qG1 qD1 qg1 qA0 qg2 qA1 qB1 qA2 qB2 qHd1 qHd2 qHp1 qHp2
        | qG1 qD1 qg1 qp1 qp2 qA2 qB2 qHd1
        | qG1 qD1 qg1 qp2 qp1 qHi
        | qG1 qD1 qa1 qa2 qA qa1' qa2' qB qg qHd qHp1 qHp2 qHe1 qHe2 ];
      subst;
split; reflexivity)
  end
with U_defeq (G:context) (D:available_props) (g:co) (a b:tm) (d:AnnDefEq G D g a b) {struct d} :
