Fixpoint U_typing (G:context) (aa A:tm) (d:AnnTyping G aa A) {struct d} :
  forall A', AnnTyping G aa A' -> erase_tm A = erase_tm A' :=
  match d as d0 in AnnTyping G0 a0 A0 return (forall A', AnnTyping G0 a0 A' -> erase_tm A0 = erase_tm A') with
  | An_Star G0 HC => fun A' d' => ltac:(inversion d'; subst; reflexivity)
  | An_Var G0 x A0 HC Hb => fun A' d' => ltac:(inversion d'; subst;
        assert (Tm A0 = Tm A') as Hu by (eapply AnnCtx_binds_unique; eauto);
        injection Hu as HA; rewrite HA; reflexivity)
  | An_Pi L G0 rho A0 B0 Hbody HA => fun A' d' => ltac:(inversion d'; subst; reflexivity)
  | An_Abs L G0 rho A0 ab B0 HA Hbody HR => fun A' d' => ltac:(
      inversion d'; subst; cbn [erase_tm];
      match goal with
      | Hbody' : forall x, x \notin ?Lx -> AnnTyping ((x ~ Tm A0) ++ G0) (open_tm_wrt_tm ab (a_Var_f x)) (open_tm_wrt_tm ?Bv (a_Var_f x)) |- a_Pi rho (erase_tm A0) (erase_tm B0) = a_Pi rho (erase_tm A0) (erase_tm ?Tv) =>
          destruct (atom_fresh (L \u Lx \u occ_tm (erase_tm B0) \u occ_tm (erase_tm Bv))) as [z Hz];
          assert (Hz1 : z \notin L) by fsetdec;
          assert (Hz2 : z \notin Lx) by fsetdec;
          pose proof (@U_typing (z ~ Tm A0 ++ G0) (open_tm_wrt_tm ab (a_Var_f z)) (open_tm_wrt_tm B0 (a_Var_f z)) (Hbody z Hz1) (open_tm_wrt_tm Bv (a_Var_f z)) (Hbody' z Hz2)) as He;
          rewrite erase_open_tm' in He; rewrite erase_open_tm' in He;
          assert (erase_tm B0 = erase_tm Bv) as HB by (eapply open_inj_tm; eauto);
          rewrite HB; reflexivity
      end)
  | An_App G0 b rho ab B0 A0 Htyp Ha => fun A' d' => ltac:(
      inversion d'; subst;
      match goal with
      | H : AnnTyping G0 b (a_Pi rho ?A1 ?B1) |- erase_tm (open_tm_wrt_tm B0 ab) = erase_tm (open_tm_wrt_tm ?Tv ab) =>
          pose proof (@U_typing G0 b (a_Pi rho A0 B0) Htyp (a_Pi rho A1 B1) H) as He;
          cbn [erase_tm] in He; assert (erase_tm B0 = erase_tm B1) as HB by (injection He; auto);
          rewrite erase_open_tm'; rewrite erase_open_tm'; rewrite HB; reflexivity
      end)
  | An_Conv G0 ab g B0 A0 Htyp Hde Hwf => fun A' d' => ltac:(
      inversion d'; subst;
      match goal with
